	// /cli/auth returns 503.
	FrontendFS fs.FS

	// TokenEndpointURL is the IdP's /api/auth/token URL as seen from the RP
	// side. In-process it is typically the server's own baseURL; in a split
	// deployment it is the IdP origin. Also fed into IdpCapabilities'
	// TokenEndpointClient construction — see NewIdpCapabilities.
	TokenEndpointURL string

	// ConsoleClientSecret is the RP credential this server presents when
	// calling the IdP's /api/auth/token to finalise a console session. Fed
	// into NewIdpCapabilities alongside TokenEndpointURL; the matching
	// client_id lives on IdpCapabilities.ConsoleClientID.
	ConsoleClientSecret string

	// RepoBridge is the entiredb RepoAdmin client. If nil, handleCreateRepo
	// responds 202 (provisioning) on every attempt so the reconciler closes
	// the loop when a client is eventually configured; admin delete-repo
	// proceeds with core-side cleanup and logs the skipped data-plane call.
	RepoBridge RepoBridge

	// TrustEnabler serves the admin enable-trust-root surface; nil leaves it
	// unregistered (the flag off, or dev/tests).
	TrustEnabler TrustEnabler

	// TrustReader reads read-only RSL trust state from the data plane for the
	// admin trust card (GET /api/admin/repos/{id}/trust). nil disables the
	// read, so the card reports "status unavailable". The production wiring
	// passes the same *repoadmin.Router used for RepoBridge.
	TrustReader TrustReader

	// TrustIntentReader reads a repo's trust-publication intents for the admin
	// trust card's operational section. The production wiring passes the same
	// *nativemirror.Service used for NativeMirrors; nil omits the section.
	TrustIntentReader TrustIntentReader

	// ClusterFixtureEnv selects the embedded cluster fixture the trust card
	// reads the fleet root profile from (staging, prod, or local). Empty
	// leaves the target-root-profile and preflight view unavailable.
	ClusterFixtureEnv string

	// AllowedClusterDomain enables /api/authz/debug-bounce when set:
	// `cluster` and `return_to` host params must equal or be a subdomain
	// of this suffix (e.g. "partial.to"). Empty disables the endpoint.
	AllowedClusterDomain string

	// JurisdictionHandoffReturnToHosts enables GET
	// /api/auth/resolve-jurisdiction when set: `return_to` must exactly
	// match one of these hosts (e.g. "auth.partial.to"). Empty disables the
	// endpoint.
	JurisdictionHandoffReturnToHosts []string

	// LoginStartURL is the BFF's jurisdictional login-start URL. The global
	// router bounces here when it can't complete a handback (invalid/expired
	// state), and its origin is the bare-root redirect target. Empty disables
	// both (callers degrade to the auth error page / landing).
	LoginStartURL string

	// ClusterAdminTransport is the mTLS *http.Transport used by the
	// cluster-admin proxy (handlers in cluster_handlers.go) to dial
	// entiredb's :8281 svctok listener at cluster.InternalURL. Same
	// transport as the repoadmin bridge — one PCA-issued cert per pod,
	// used both as server (entire-core's own :8281 mTLS server) and
	// client. Nil disables the cluster-admin proxy: handlers respond
	// with 503 so deploys that haven't wired the bundle don't 500.
	ClusterAdminTransport *http.Transport

	// InternalTokenEndpoint is the OAuth issuer base URL (no
	// /oauth/token suffix) the cluster-admin proxy POSTs to for an
	// on-behalf-of ops-access JWT. InternalTokenClient is the mTLS
	// loopback client that dials it (ServerName pinned to a DNS SAN on
	// the client cert, so the listener handler stamps cnf from the
	// presented leaf). Both empty/nil falls the proxy back to the
	// in-process IssueOpsToken signer — the same dev
	// degradation the repoadmin bridge takes.
	InternalTokenEndpoint string
	InternalTokenClient   *http.Client

	// TestMode disables rate limiting (per-IP and per-principal). Tests
	// drive many requests from one loopback IP and reuse a single
	// principal, which the real limits would turn into flaky 429s.
	// Production wiring (entirecore) leaves this false.
	TestMode bool

	// DeployEnv labels the deployment (ENTIRE_DEPLOY_ENV: staging or
	// production in fleet; empty in local dev). Surfaced on /api/info as
	// environment so the admin console can show which world this is.
	DeployEnv string

	// AccountDeletionEnabled is the launch gate for self-service account
	// deletion (ENTIRE_ACCOUNT_DELETION_ENABLED, default false). When off,
	// DELETE /me + /me/cancel-deletion + /me/deletion-preview are not registered
	// (404) — so the feature ships dark and can't be triggered even by direct
	// API call until flipped on in lockstep with the frontend flag. The reaper
	// honors the same flag (no-op when off), so the already-scheduled CronJob
	// stays inert until launch.
	AccountDeletionEnabled bool
}

func NewServer(cfg Config) *Server {
	s := &Server{
		mux:                         http.NewServeMux(),
		identity:                    cfg.Identity,
		handleCache:                 NewHandleStateCache(stateCheckTTL, cfg.Identity),
		jurisdictionVerifier:        cfg.JurisdictionVerifier,
		jurisdictionAudience:        cfg.JurisdictionAudience,
		authz:                       cfg.Authz,
		resource:                    cfg.Resource,
		automation:                  cfg.Automation,
		erasureOutbox:               cfg.ErasureOutbox,
		erasureLedger:               cfg.ErasureLedger,
		emailOutbox:                 cfg.EmailOutbox,
		ceoWelcomeEnabled:           cfg.CEOWelcomeEnabled,
		providers:                   cfg.Providers,
		githubTokens:                cfg.GitHubTokens,
		githubPerms:                 cfg.GitHubPerms,
		oidcFed:                     cfg.OIDCFed,
		domainAudit:                 cfg.DomainAudit,
		githubUserAPI:               cfg.GitHubUserAPI,
		userPermsSync:               cfg.UserPermsSync,
		availableMirrorsReadModel:   cfg.AvailableMirrorsReadModel,
		availableMirrorsUserFresh:   cfg.AvailableMirrorsUserFreshness,
		permsUserSyncTTL:            cfg.PermsUserSyncTTL,
		githubTokenIdentityExchange: cfg.GitHubTokenIdentityExchange,
		mirrorRepos:                 cfg.MirrorRepos,
		mirrorRequests:              cfg.MirrorRequests,
		mirrorRequestPublisher:      cfg.MirrorRequestPublisher,
		nativeMirrors:               cfg.NativeMirrors,
		nativeMirrorEnabled:         cfg.NativeMirrorEnabled,
		nativeMirrorCreateEnabled:   cfg.NativeMirrorCreateEnabled,
		mirrorPermsBackfill:         cfg.MirrorPermsBackfill,
		resyncPub:                   cfg.ResyncPub,
		lifecycleEvents:             cfg.LifecycleEvents,
		analytics:                   cfg.Analytics,
		ghAppCaps:                   cfg.GitHubAppCaps,
		workos:                      cfg.WorkOS,
		githubClientID:              cfg.GitHubClientID,
		githubClientSecret:          cfg.GitHubClientSecret,
		githubRedirectURL:           cfg.GitHubRedirectURL,
		githubAppPublicURL:          strings.TrimRight(cfg.GitHubAppPublicURL, "/"),
		authBaseURL:                 cfg.AuthBaseURL,
		consoleURL:                  cfg.ConsoleURL,
		ciWebhooksURL:               strings.TrimRight(cfg.CIWebhooksURL, "/"),
		ciWebhooksURLs:              normalizeCIWebhooksURLs(cfg.CIWebhooksURLs),
		firstPartyOrigins:           cfg.FirstPartyOrigins,
		primaryLoginURL:             strings.TrimRight(cfg.PrimaryLoginURL, "/"),
		mode:                        cfg.Mode,
		jurisdiction:                cfg.Jurisdiction,
		deployEnv:                   cfg.DeployEnv,
		accountDeletionEnabled:      cfg.AccountDeletionEnabled,
		cookie:                      cfg.Cookie,
		oauthStateStore:             cfg.OAuthStateStore,
		jurisdictionHosts:           cfg.JurisdictionHosts,
		jurisdictionAuthHosts:       cfg.JurisdictionAuthHosts,
		jurisdictionAPIHosts:        cfg.JurisdictionAPIHosts,
		entireAPIInternalURL:        cfg.EntireAPIInternalURL,
		siblingAuthBaseURLs:         cfg.SiblingAuthBaseURLs,
		routerCaps:                  cfg.RouterCaps,
		jurCaps:                     cfg.JurisdictionCaps,
		waitlistMode:                cfg.WaitlistMode,
		idpCaps:                     cfg.IdpCaps,
		frontendFS:                  cfg.FrontendFS,
		tokenEndpointURL:            cfg.TokenEndpointURL,
		repoBridge:                  repoBridgeOrUnconfigured(cfg.RepoBridge),
		trustReader:                 cfg.TrustReader,
		trustEnabler:                cfg.TrustEnabler,
		trustIntents:                cfg.TrustIntentReader,
		clusterFixtureEnv:           cfg.ClusterFixtureEnv,
		allowedClusterDomain:        cfg.AllowedClusterDomain,
		handoffReturnToHosts:        cfg.JurisdictionHandoffReturnToHosts,
		loginStartURL:               cfg.LoginStartURL,
		clusterAdminTransport:       cfg.ClusterAdminTransport,
		internalTokenEndpoint:       cfg.InternalTokenEndpoint,
		internalTokenClient:         cfg.InternalTokenClient,
		oauthStates:                 make(map[string]oauthState),
	}
	var siblingIssuers []string
	for _, u := range cfg.SiblingAuthBaseURLs {
		if u == "" || u == s.authBaseURL {
			continue
		}
		siblingIssuers = append(siblingIssuers, u)
	}
	if len(siblingIssuers) > 0 {
		// No audience pinned: repo-push audiences vary per repo and cluster,
		// while account access tokens name the sibling's own AuthBaseURL.
		// The github-access-token handler classifies the verified shape.
		s.siblingSubjectVerifiers = jwtverify.NewTrustedIssuers(siblingIssuers, siblingJWKSCacheTTL,
			jwtverify.WithObserver(authn.RecordTokenVerifiedObserver("sibling")),
			jwtverify.WithFetchObserver(authn.RecordJWKSFetchObserver("sibling")),
			jwtverify.WithHTTPClient(authn.JWKSHTTPClient()))
	}
	if cfg.GitHubPerms != nil {
		s.availableMirrorsPerms = newReadinessCachingPermsSource(cfg.GitHubPerms)
	}
	// regional, cluster, and gitJobsPub mirror jurCaps's fields one-for-one
	// (see the jurCaps field doc comment): populated together here, nil
	// together on a global server, so the many existing call sites reading
	// them directly need no change — only the handler-boundary gates that
	// used to check these fields individually now check jurCaps as a group.
	if cfg.JurisdictionCaps != nil {
		s.regional = cfg.JurisdictionCaps.Regional
		s.cluster = cfg.JurisdictionCaps.Cluster
		s.gitJobsPub = cfg.JurisdictionCaps.GitJobsPub
	}
	s.platformAdminCache = newPlatformAdminCache(s.checkPlatformAdmin)
	// Hand the cache's invalidator to the identity Store so
	// DeleteAccount / CreateAccountWithHandle drop the LRU entry instead
	// of waiting out the 5s TTL. Only the concrete *identity.Store
	// supports this — interface-only fakes used in some tests don't,
	// and skipping silently is fine: those tests don't exercise resignup
	// timing.
	if store, ok := cfg.Identity.(*identity.Store); ok {
		store.SetHandleCacheInvalidator(s.handleCache)
	}
	s.ipRateLimit, s.userRateLimit, s.stsRateLimit = newRateLimiters(cfg.TestMode)
	s.routes()
	return s
}

// RunRateLimitCleanup runs the rate-limiter eviction loop, blocking until ctx
// is cancelled, then returns nil. This is the blocking form the serve-layer
// subsystem runner drives (COR-832); the loop itself lives in
// ratelimit.StartCleanup, which spawns the ticker goroutine and stops it on
// ctx.Done. Returning nil only after ctx cancellation means the runner treats
// the exit as a clean shutdown rather than a premature exit.
//
//nolint:unparam // error result is dictated by the subsystem.run func(ctx) error contract; cleanup never fails.
func (s *Server) RunRateLimitCleanup(ctx context.Context) error {
	ratelimit.StartCleanup(ctx, s.ipRateLimit, s.userRateLimit, s.stsRateLimit)
	<-ctx.Done()
	return nil
}

// STSTokenHandler returns the bare /api/authz/sts/token handler so an
// alternate listener (e.g. entire-core's internal mTLS listener for
// service-to-service callers) can mount it without going through the
// public mux. Most exchanges use the form's subject_token as the
// credential; internal-only exchanges may instead rely on transport-level
// identity (mTLS peer cert workload) that the alternate listener gates
// before this handler runs.
func (s *Server) STSTokenHandler() http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// Fail safe rather than nil-deref: the backup-access branch inside
		// handleSTSTokenExchange reaches s.idpCaps.JWT at request time with
		// no earlier guard. This path is unreachable in production today —
		// the internal mTLS listener only mounts this handler in
		// regional, where idpCaps is always wired. Kept as
		// defense in depth per COR-858, matching OAuthTokenHandler's guard.
		// Checked here rather than inside handleSTSTokenExchange itself so
		// the public mux's own direct registration of that handler (the
		// HandleFunc in registerControlPlaneRoutes, called via
		// registerSessionAuthRoutes, likewise regional-only) is
		// untouched.
		if s.idpCaps == nil {
			http.Error(w, `{"error":"sts token endpoint not configured"}`, http.StatusServiceUnavailable)
			return
		}
		s.handleSTSTokenExchange(w, r)
	}
}

// OAuthTokenHandler returns the pkg/op /oauth/token handler so the
// internal mTLS listener can mount it alongside the legacy
// /api/authz/sts/token. Service-to-service callers (mirror-pipeline,
// peregrine) post RFC 8693 token-exchange requests here after COR-233
// drained the repo-access / ops-access branches off the legacy STS path.
//
// The subject_token still authorizes the exchange — the alternate
// listener's mTLS workload check is defence-in-depth, not the primary
// credential.
func (s *Server) OAuthTokenHandler() http.Handler {
	if s.idpCaps == nil {
		return http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
			http.Error(w, `{"error":"oauth token endpoint not configured"}`, http.StatusServiceUnavailable)
		})
	}
	return s.idpCaps.OIDCProvider
}

// crossJurisHint builds the AuthMiddleware hint from server state.
// Returns nil when there are no siblings or no AuthBaseURL configured
// (no cross-juris recovery is possible, so the middleware skips the
// structured hint and falls back to bare 401).
func (s *Server) crossJurisHint() *CrossJurisHint {
	if len(s.siblingAuthBaseURLs) == 0 || s.authBaseURL == "" {
		return nil
	}
	tokenURL := s.tokenEndpointURL
	if tokenURL == "" {
		tokenURL = strings.TrimRight(s.authBaseURL, "/") + "/oauth/token"
	}
	return &CrossJurisHint{
		SiblingAuthBaseURLs: s.siblingAuthBaseURLs,
		TokenExchangeURL:    tokenURL,
		LocalAuthBaseURL:    s.authBaseURL,
	}
}

// IsJurisdictionToken reports whether claims came from a jurisdiction
// token — i.e. its audience is the one the jurisdiction-token verifier
// pins. AuthMiddleware only ever produces such claims via that verifier
// (which pins aud exactly and requires scope=openid), so the audience
// match is a reliable discriminator.
//
// The /api/v1 mutation gate uses this to treat a jurisdiction token as a
// full principal: identity is proven, and SpiceDB authorizes every
// operation regardless of token shape. Returns false when no
// jurisdiction-token exchange is wired (nil verifier) or claims is nil.
func (s *Server) IsJurisdictionToken(claims *authn.Claims) bool {
	if s.jurisdictionVerifier == nil || claims == nil {
		return false
	}
	return slices.Contains(claims.Audiences, s.jurisdictionAudience)
}

// handleFederationManifest serves GET /.well-known/entire-federation.
// The body is the public allow-list a CLI uses to decide whether a 421
// redirect target (home_core_url) is in this core's federation — see
// internal/cliauth/cross_juris_transport.go. The list is not a secret
// (the same hosts appear in /api/info's jurisdiction map), so the
// endpoint is public.
//
// Returns an empty list when no siblings are configured (single-region,
// global, single-region regional). The CLI treats that as "no 421
// follow allowed from this origin" — defence-in-depth against an
// attacker setting up a hostile single-region core that returns 421
// with off-host home_core_url.
func (s *Server) handleFederationManifest(w http.ResponseWriter, r *http.Request) {
	hosts := s.siblingAuthBaseURLs
	if hosts == nil {
		hosts = []string{}
	}
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("Cache-Control", "public, max-age=300")
	body := struct {
		PeerAuthHosts []string `json:"peer_auth_hosts"`
	}{PeerAuthHosts: hosts}
	if err := json.NewEncoder(w).Encode(body); err != nil {
		slogutil.Warn(r.Context(), "federation manifest encode failed", slog.String("error", err.Error()))
	}
}

func (s *Server) Handler() http.Handler {
	return s.wrapPublicChain(s.mux, "entire-core")
}

// wrapPublicChain applies the public middleware stack — auth (so claims
// reach request context, which downstream handlers gate on), logging, CORS,
// otel tracing with the matched-route span-name formatter, and the ENT-754
// security headers — around mux, then resolves the route pattern. Handler()
// and WrapPublicMux both route through here so the chain is defined in
// exactly one place. otelService is the span service name; mux is also
// passed to resolveRoutePattern so it can pre-resolve the matched pattern
// for the span formatter.
func (s *Server) wrapPublicChain(mux *http.ServeMux, otelService string) http.Handler {
	var h http.Handler = mux
	// The limiters are nil only on a Server built without NewServer (handler
	// unit tests); a nil limiter means "not wired", same as the struct's other
	// optional dependencies. NewServer always sets both, so production is
	// always limited.
	//
	// Per-principal limiting runs innermost, inside AuthMiddleware, so the
	// principal is on the context (and only for the authenticated API surface).
	if s.userRateLimit != nil {
		h = s.userRateLimitMiddleware(h)
	}
	// idpCaps groups Verifier/ConsoleSessionStore/ConsoleCookie/JWT (see
	// IdpCapabilities); the per-field OR below preserves the exact wrap
	// condition from before the group existed — a partial idpCaps (some
	// in-package tests wire only one of these) still wraps AuthMiddleware
	// exactly as a partial flat-field Config used to.
	if s.idpCaps != nil && (s.idpCaps.Verifier != nil || s.idpCaps.ConsoleSessionStore != nil) {
		h = AuthMiddleware(s.idpCaps.Verifier, s.jurisdictionVerifier, s.idpCaps.ConsoleSessionStore, s.idpCaps.ConsoleCookie, s.handleCache, s.platformAdminCache, s.crossJurisHint(), s.idpCaps.JWT)(h)
	}
	h = LogMiddleware(h)
	// Per-IP limiting is the outermost dispatch gate: after CORS/OTel (so
	// preflights and tracing aren't rate-limited) but before any handler runs.
	if s.ipRateLimit != nil {
		h = s.ipRateLimit.Middleware(h)
	}
	h = httputil.CORSMiddleware(h)
	h = setRouteAttr(h)
	h = otelhttp.NewHandler(h, otelService,
		otelhttp.WithSpanNameFormatter(matchedPatternSpanName),
	)
	h = securityHeaders(h)
	return resolveRoutePattern(mux, h)
}

// matchedPatternSpanName names a server span after the mux pattern
// resolveRoutePattern stashed up front (e.g. "GET /repos/{id}"), falling back
// to "<METHOD> [unmatched]" so unrouted requests stay low-cardinality.
func matchedPatternSpanName(_ string, r *http.Request) string {
	if pattern, _ := routePatternFromContext(r.Context()); pattern != "" {
		return pattern
	}
	return r.Method + " [unmatched]"
}

// TraceMuxHandler wraps mux in the same route-aware tracing stack
// wrapPublicChain applies — span names from the matched mux pattern (resolved
// up front, since otelhttp names the span before the mux dispatches) plus the
// http.route attribute recorded after dispatch, which is what lets the
// Datadog OTLP receiver derive a "<METHOD> <route>" resource instead of
// collapsing every request to its bare method. For extra listeners (the
// internal mTLS listener) whose muxes don't take the public auth/CORS chain.
func TraceMuxHandler(mux *http.ServeMux, otelService string) http.Handler {
	h := setRouteAttr(mux)
	h = otelhttp.NewHandler(h, otelService,
		otelhttp.WithSpanNameFormatter(matchedPatternSpanName),
	)
	return resolveRoutePattern(mux, h)
}

// resolveRoutePattern wraps the otelhttp layer so the matched mux pattern is
// available at span-creation time. otelhttp.NewHandler computes the span
// name in WithSpanNameFormatter before the inner handler runs, but Go's
// http.ServeMux only populates r.Pattern when it dispatches the matched
// handler — i.e. inside the otel handler. We resolve the pattern up front
// with mux.Handler (idempotent; no dispatch) and stash it on the context
// for the formatter to read. The mux still does its own routing as normal.
//
// It also seeds the RecordedRoute slot here — outermost, outside otelhttp — so
// a sub-router mounted under a catch-all (the huma API at "/api/v1/", whose
// per-operation route mux.Handler can't see up front) can record its matched
// route for setRouteAttr to prefer. The pointer survives the request clones the
// auth middleware makes, so the writer and reader share one slot.
func resolveRoutePattern(mux *http.ServeMux, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		ctx := WithRecordedRoute(r.Context())
		if _, pattern := mux.Handler(r); pattern != "" {
			ctx = withRoutePattern(ctx, pattern)
		}
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

type routePatternKey struct{}

func withRoutePattern(ctx context.Context, pattern string) context.Context {
	return context.WithValue(ctx, routePatternKey{}, pattern)
}

func routePatternFromContext(ctx context.Context) (string, bool) {
	p, ok := ctx.Value(routePatternKey{}).(string)
	return p, ok
}

func (s *Server) domainAuditLog(r *http.Request, accountID model.AccountID, eventType, resourceType, resourceID string, meta map[string]any) {
	s.DomainAuditLog(r.Context(), accountID, eventType, resourceType, resourceID, meta)
}

// DomainAuditLog is the ctx-based counterpart to domainAuditLog for
// coreapi (huma) handlers that don't carry an *http.Request. Failures
// log a warning and are swallowed — audit writes are best-effort.
func (s *Server) DomainAuditLog(ctx context.Context, accountID model.AccountID, eventType, resourceType, resourceID string, meta map[string]any) {
	if s.domainAudit == nil {
		return
	}
	if err := s.domainAudit.Log(ctx, accountID, eventType, resourceType, resourceID, meta); err != nil {
		slogutil.Warn(ctx, "domain audit failed", slog.Any("error", err))
	}
}

func (s *Server) routes() {
	switch s.mode {
	case "global":
		s.registerGlobalRoutes()
	case "reaper":
		// The account-deletion reaper builds a *Server only to call
		// FinalizeAccountDeleteCore directly (ADR 20260707); it never serves
		// HTTP and wires none of the session/auth/IdP deps. Register only the
		// mode-agnostic common routes — registerSessionAuthRoutes would deref a
		// nil idpCaps.
		s.registerCommonRoutes()
	default:
		// "regional", plus the empty mode tests construct servers with.
		s.registerRegionalRoutes()
	}
}

func (s *Server) registerCommonRoutes() {
	s.mux.HandleFunc("GET /healthz", s.handleHealth)
	s.mux.HandleFunc("GET /api/info", s.handleInfo)
	// Federation manifest is mode-agnostic — every entire-core mode
	// publishes it, even if the list is empty. The CLI's 421-follow
	// trust gate calls this on every responding origin, so a missing
	// route would force it to refuse cross-juris redirects across the
	// whole fleet on a partial rollout.
	s.mux.HandleFunc("GET /.well-known/entire-federation", s.handleFederationManifest)
}

func (s *Server) registerAuthenticatedRoutes() {
	// Identity / audit / control-plane / service-account user-facing JSON
	// routes moved to /api/v1/* served by core/coreapi (see ADR
	// 20260522-repo-openapi-huma.md, applied to the core surface). Mirror
	// create/delete now live as CreateMirrorPlacement / DeleteMirrorPlacement
	// (mirrors.go), called directly by coreapi.MirrorService — no legacy
	// /api/mirrors route remains.
}

func (s *Server) registerControlPlaneRoutes() {
	// Admin endpoints remain on the legacy mux (planned for ConnectRPC,
	// not huma). Anything pre-existing on /api/admin/* stays.
	s.mux.Handle("GET /api/admin/users", RequireSession(http.HandlerFunc(s.handleAdminUsers)))
	s.mux.Handle("GET /api/admin/service-accounts", RequireSession(http.HandlerFunc(s.handleAdminListServiceAccounts)))
	s.mux.Handle("GET /api/admin/platform-admins", RequireSession(http.HandlerFunc(s.handleListPlatformAdmins)))
	s.mux.Handle("POST /api/admin/platform-admins", RequireSession(http.HandlerFunc(s.handleGrantPlatformAdmin)))
	s.mux.Handle("DELETE /api/admin/platform-admins/{handle...}", RequireSession(http.HandlerFunc(s.handleRevokePlatformAdmin)))
	s.mux.Handle("GET /api/admin/platform-admin-readers", RequireSession(http.HandlerFunc(s.handleListPlatformAdminReaders)))
	s.mux.Handle("POST /api/admin/platform-admin-readers", RequireSession(http.HandlerFunc(s.handleGrantPlatformAdminReader)))
	s.mux.Handle("DELETE /api/admin/platform-admin-readers/{handle...}", RequireSession(http.HandlerFunc(s.handleRevokePlatformAdminReader)))
	s.mux.Handle("GET /api/admin/platform-backup-admins", RequireSession(http.HandlerFunc(s.handleListPlatformBackupAdmins)))
	s.mux.Handle("POST /api/admin/platform-backup-admins", RequireSession(http.HandlerFunc(s.handleGrantPlatformBackupAdmin)))
	s.mux.Handle("DELETE /api/admin/platform-backup-admins/{handle...}", RequireSession(http.HandlerFunc(s.handleRevokePlatformBackupAdmin)))
	s.mux.Handle("GET /api/admin/platform-deploy-operators", RequireSession(http.HandlerFunc(s.handleListPlatformDeployOperators)))
	s.mux.Handle("POST /api/admin/platform-deploy-operators", RequireSession(http.HandlerFunc(s.handleGrantPlatformDeployOperator)))
	s.mux.Handle("DELETE /api/admin/platform-deploy-operators/{account_id}", RequireSession(http.HandlerFunc(s.handleRevokePlatformDeployOperator)))
	s.mux.Handle("GET /api/admin/mirrors", RequireSession(http.HandlerFunc(s.handleAdminListMirrors)))
	s.mux.Handle("POST /api/admin/mirrors", RequireSession(http.HandlerFunc(s.handleAdminCreateMirror)))
