// registerSessionAuthRoutes registers the regional route set: the SPA file
// server, common+login+authenticated+control plane groups, and every
// IdP/RP/logout endpoint. Global mode does not call this — it serves a
// minimal landing page with a different route set.
func (s *Server) registerSessionAuthRoutes() {
	s.registerCommonRoutes()
	s.mux.Handle("/", noEdgeCache(noDirListing(staticFS, http.FileServerFS(staticFS))))
	// Admin SPA bundle is privileged source (ENT-755): gate /admin.html and
	// the whole /admin/ asset subtree behind a platform-admin check. These
	// patterns are more specific than the "/" catch-all so they win; the
	// rest of the static tree (console, login pages, svgs) stays public.
	// No method prefix — HEAD/GET alike must be gated.
	adminBundle := s.gateAdminBundle(noDirListing(staticFS, http.FileServerFS(staticFS)))
	s.mux.Handle("/admin.html", adminBundle)
	s.mux.Handle("/admin/", adminBundle)
	s.mux.HandleFunc("GET /admin/{$}", func(w http.ResponseWriter, r *http.Request) {
		http.Redirect(w, r, "/admin.html", http.StatusTemporaryRedirect)
	})
	// The user-facing console SPA that used to be served at "/" was retired.
	// A bare "/" now routes by role (see handleConsoleRoot). This exact-match
	// pattern is more specific than the "/" catch-all, so it wins for the root
	// while the catch-all still serves the remaining static assets.
	s.mux.HandleFunc("GET /{$}", s.handleConsoleRoot)
	s.registerLoginRoutes()
	s.registerAuthenticatedRoutes()
	s.registerControlPlaneRoutes()
	s.mux.HandleFunc("GET /.well-known/jwks.json", s.handleJWKS)
	s.mux.Handle("GET /keys", s.idpCaps.OIDCProvider)
	// /.well-known/openid-configuration is pkg/op's discovery document plus the
	// RFC 8705 §3.3 cert-bound-token advertisement, which pkg/op's
	// DiscoveryConfiguration struct can't express (see handleOpenIDConfiguration).
	s.mux.HandleFunc("GET /.well-known/openid-configuration", s.handleOpenIDConfiguration)
	// RFC 8414 OAuth Authorization Server Metadata. MCP clients (including
	// Claude) probe this OAuth-specific path before falling back to the OIDC
	// document, so we re-emit the same discovery values here — no second
	// source of truth.
	s.mux.HandleFunc("GET /.well-known/oauth-authorization-server", s.handleOAuthAuthServerMetadata)
	s.mux.Handle("GET /authorize", captureResourceParam(s.idpCaps.OIDCProvider))
	// /authorize/callback issues the final 302 to the RP's redirect_uri with
	// the auth code. Wrap it to append iss=<authBaseURL> per RFC 9207 so
	// cross-jurisdiction RPs route the token exchange to the issuing region's
	// /oauth/token instead of the original /authorize host.
	s.mux.Handle("GET /authorize/callback", withIssuerOnRedirect(s.idpCaps.OIDCProvider, s.authBaseURL))
	s.mux.Handle("POST /device_authorization", s.idpCaps.OIDCProvider)
	allow, err := newOriginAllowlist(s.authBaseURL, s.consoleURL, s.firstPartyOrigins...)
	if err != nil {
		// AuthBaseURL + ConsoleURL are required on every mode that mounts
		// /oauth/token (entirecore.Config). An error here is a misconfigured
		// deployment, not a recoverable condition.
		panic(fmt.Errorf("oauth origin allowlist: %w", err))
	}
	// Log the resolved allowlist at startup so an operator who sets
	// ENTIRE_CORE_FIRST_PARTY_ORIGINS in fleet can confirm from logs that
	// their origin landed — without it the only check is to attempt a
	// cookie-bridge call and watch for a reject (COR-361).
	slogutil.Info(context.Background(), "oauth /oauth/token origin allowlist configured",
		slog.Any("origins", allow.origins))
	// Only POST is mounted: an OPTIONS preflight to /oauth/token is answered by
	// the global wildcard CORSMiddleware (ACAO:* + no Allow-Credentials), which
	// a credentialed preflight rejects. requireFirstPartyOrigin emits the
	// credentialed CORS on the POST itself, so the SPA exchange must stay a CORS
	// simple request (form-urlencoded, no author headers) to avoid a preflight.
	// liftFormClientCredentials lets the SPA carry client_id in the body instead
	// of an Authorization header (which would force a preflight), supplying the
	// Basic client auth pkg/op requires (COR-372). Chain: origin/CORS gate →
	// cookie→subject_token → client_id→Basic → pkg/op.
	s.mux.Handle("POST /oauth/token", requireFirstPartyOrigin(allow, s.idpCaps.LoginCookie, s.idpCaps.RefreshCookie,
		injectCookieSubjectToken(s.idpCaps.LoginCookie, s.authBaseURL,
			liftFormClientCredentials(s.idpCaps.OIDCProvider))))
	s.mux.Handle("GET /userinfo", s.idpCaps.OIDCProvider)
	s.mux.Handle("POST /userinfo", s.idpCaps.OIDCProvider)
	s.mux.Handle("POST /oauth/introspect", s.idpCaps.OIDCProvider)
	s.mux.Handle("POST /revoke", s.idpCaps.OIDCProvider)
	// Session-based auth endpoints.
	s.mux.HandleFunc("GET /api/auth/login", s.handleConsoleLogin)
	s.mux.HandleFunc("GET /api/auth/callback", s.handleAuthCallback)
	// /api/auth/cli/decision is browser-session-gated by AuthMiddleware.
	// RequireSession additionally rejects narrowed api-access tokens — the
	// CLI approval flow is a session-issuing op.
	s.mux.Handle("POST /api/auth/cli/decision", RequireSession(http.HandlerFunc(s.handleCLIDecision)))
	// Refresh-token family management. RequireSession-gated — caller is the
	// JWT subject; revoke is scoped to that account so users can't touch
	// each other's families. The gate also blocks narrowed api-access
	// tokens from listing/revoking refresh families.
	s.mux.Handle("GET /api/auth/tokens", RequireSession(http.HandlerFunc(s.handleListAuthTokens)))
	// /current is registered before the {family_id} variant so the literal
	// segment shadows the wildcard. (Go 1.22 servemux precedence makes this
	// deterministic regardless of registration order, but pairing them
	// keeps the intent readable.)
	s.mux.Handle("DELETE /api/auth/tokens/current", RequireSession(http.HandlerFunc(s.handleRevokeCurrentAuthToken)))
	s.mux.Handle("DELETE /api/auth/tokens/{family_id}", RequireSession(http.HandlerFunc(s.handleRevokeAuthToken)))
	// SPA approval page + assets. /cli/auth checks for a session and
	// redirects unauthenticated users through /api/auth/login first.
	s.mux.HandleFunc("GET /cli/auth", s.handleCLIAuthPage)
	s.mux.HandleFunc("GET /cli/assets/", s.handleCLIAssets)
	// CLI login interstitial: shows which host you're authenticating against
	// and dispatches to /api/auth/authorize on click. Used by the entiredb /
	// entire-core CLIs running the loopback OAuth flow.
	s.mux.HandleFunc("GET /cli/login", s.handleCLILoginPage)
	// System login — break-glass pre-shared key authentication.
	s.mux.Handle("POST /api/auth/system/login", http.HandlerFunc(s.handleSystemLogin))
	// Console-side logout initiator: clears the console session and redirects
	// to the IdP's /api/auth/end-session to clear the IdP cookie on its own origin.
	s.mux.HandleFunc("GET /logout", s.handleConsoleLogout)
	// Post-logout landing page: shown after both console and IdP sessions are cleared.
	s.mux.HandleFunc("GET /logged-out", serveStaticFile("logged-out.html"))
	// IdP-side session terminator: clears the IdP cookie and redirects to the
	// validated return_to URI registered by the client.
	s.mux.HandleFunc("GET /api/auth/end-session", s.handleEndSession)
}

func (s *Server) registerGlobalRoutes() {
	s.registerCommonRoutes()
	// Global serves a minimal landing page, not the full SPA.
	s.mux.HandleFunc("GET /{$}", s.handleGlobalRoot)
	// Brand assets used by the landing page. The full
	// staticFS catch-all is deliberately not mounted on global — exposing
	// admin/index/etc. would render those pages against APIs that don't
	// exist in global mode. Listing the assets explicitly keeps the
	// global host surface narrow.
	s.mux.HandleFunc("GET /favicon.svg", serveStaticFile("favicon.svg"))
	s.mux.HandleFunc("GET /entire-lockup-light.svg", serveStaticFile("entire-lockup-light.svg"))
	// External scripts for the two global-mode pages. They used to be inline
	// <script> blocks; extracting them lets the CSP drop script-src
	// 'unsafe-inline'. The staticFS catch-all that would otherwise serve them
	// isn't mounted on global, so these need explicit routes.
	s.mux.HandleFunc("GET /global-landing.js", serveStaticFile("global-landing.js"))
	// Global OAuth — zero-scope router handlers. New users are geo-routed by
	// the callback; there is no region-picker page any more.
	s.mux.HandleFunc("GET /api/auth/{provider}/login", s.handleRouterProviderLogin)
	s.mux.HandleFunc("GET /api/auth/{provider}/callback", s.handleProviderGlobalCallback)
	// Debug-bounce router: validates the inbound cluster + return_to,
	// runs zero-scope OAuth, and forwards to the user's home region's
	// /api/authz/debug-bounce after the round-trip.
	s.mux.HandleFunc("GET /api/authz/debug-bounce", s.handleGlobalDebugBounce)
	// Jurisdiction handoff: lets a trusted RP (the entire.io BFF) discover a
	// user's home jurisdiction via zero-scope GitHub OAuth.
	s.mux.HandleFunc("GET /api/auth/resolve-jurisdiction", s.handleGlobalResolveJurisdiction)
	// CLI OIDC dispatch. Global still serves no IdP of its own; these two
	// forward the CLI's OAuth entry points to the jurisdiction whose regional
	// core actually runs the login, so the CLI can hardcode one login host.
	// See core/api/global_oidc_dispatch.go.
	s.mux.HandleFunc("GET /authorize", s.handleGlobalAuthorize)
	s.mux.HandleFunc("POST /device_authorization", s.handleGlobalDeviceAuthorization)
	// No control plane, no JWKS, no token endpoint, no internal API.
}

func (s *Server) registerRegionalRoutes() {
	s.registerSessionAuthRoutes()
}

func (s *Server) handleInfo(w http.ResponseWriter, _ *http.Request) {
	info := map[string]any{"mode": s.mode, "commit": version.FullCommit}
	switch s.mode {
	case "regional":
		info["jurisdiction"] = s.jurisdiction
		info["auth_url"] = s.authBaseURL
		info["console_url"] = s.consoleURL
	case "global":
		// Global has no own auth_url/console_url — it routes by jurisdiction.
	default:
		info["auth_url"] = s.authBaseURL
		info["console_url"] = s.consoleURL
	}
	if s.deployEnv != "" {
		info["environment"] = s.deployEnv
	}
	// The jurisdiction maps are populated in every mode (empty in
	// single-host dev). Always expose them so operators can verify the
	// runtime-resolved values without grepping the running process.
	info["jurisdiction_hosts"] = s.jurisdictionHosts
	info["jurisdiction_auth_hosts"] = s.jurisdictionAuthHosts
	if providers := s.providerRegistry(); providers != nil {
		info["auth"] = map[string]any{
			"default_provider": string(providers.DefaultID()),
			"providers":        providers.Metadata(),
		}
	}
	writeJSON(w, http.StatusOK, info)
}

func (s *Server) providerRegistry() *authn.ProviderRegistry {
	if s.providers != nil {
		return s.providers
	}
	if s.githubClientID == "" {
		return nil
	}
	github := authn.NewGitHubOAuthProvider(s.githubClientID, s.githubClientSecret, s.githubRedirectURL, "", "")
	registry, err := authn.NewProviderRegistry("github", github)
	if err != nil {
		return nil
	}
	return registry
}

func (s *Server) lookupProvider(id string) (authn.OAuthProvider, error) {
	registry := s.providerRegistry()
	if registry == nil {
		return nil, errors.New("auth providers not configured")
	}
	return registry.MustLookupString(id)
}

// explicitProviderRequested reports whether the caller named a provider via
// ?provider= or ?method=, as opposed to loginProviderFromQuery silently
// resolving the registry default.
func explicitProviderRequested(r *http.Request) bool {
	return r.URL.Query().Get("provider") != "" || r.URL.Query().Get("method") != ""
}

func (s *Server) loginProviderFromQuery(r *http.Request) (authn.OAuthProvider, string, error) {
	providerID := r.URL.Query().Get("provider")
	method := r.URL.Query().Get("method")
	if method != "" {
		// method is validated below by lookupProvider (format via
		// ValidateProviderID, existence via the registry), so any registered
		// provider id is accepted here — not just the literal "github".
		if providerID != "" && providerID != method {
			return nil, "", fmt.Errorf("provider %q conflicts with method %q", providerID, method)
		}
		providerID = method
	}
	if providerID == "" {
		registry := s.providerRegistry()
		if registry == nil {
			return nil, "", errors.New("auth providers not configured")
		}
		providerID = string(registry.DefaultID())
	}
	provider, err := s.lookupProvider(providerID)
	if err != nil {
		return nil, "", err
	}
	return provider, providerID, nil
}

func (s *Server) handleJWKS(w http.ResponseWriter, r *http.Request) {
	keys, err := s.idpCaps.KeyStore.ActivePublicKeys(r.Context())
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
	writeJSON(w, http.StatusOK, jose.JSONWebKeySet{Keys: keys})
}

// discoveryDocument re-derives the discovery document pkg/op emits via
// op.CreateDiscoveryConfig — resolving the issuer from the request the same way
// pkg/op's own discovery handler does — and merges in the metadata pkg/op's
// DiscoveryConfiguration struct can't express.
//
// RFC 8705 §3.3: tls_client_certificate_bound_access_tokens advertises that the
// AS issues mutual-TLS client-certificate-bound access tokens — the strict cnf
// binding enforced on the :8281 data-plane surface. Both the OIDC and RFC 8414
// documents build on this map so the advertised endpoints, grant types
// (including the RFC 8693 token-exchange grant), S256 PKCE method, entire:*
// scopes, and the cert-bound flag can't drift between them.
func (s *Server) discoveryDocument(r *http.Request) (map[string]any, error) {
	ctx := op.ContextWithIssuer(r.Context(), s.idpCaps.OIDCProvider.IssuerFromRequest(r))
	cfg := op.CreateDiscoveryConfig(ctx, s.idpCaps.OIDCProvider, s.idpCaps.OIDCProvider.Storage())

	raw, err := json.Marshal(cfg)
	if err != nil {
		return nil, fmt.Errorf("marshal discovery config: %w", err)
	}
	var doc map[string]any
	if err := json.Unmarshal(raw, &doc); err != nil {
		return nil, fmt.Errorf("unmarshal discovery config: %w", err)
	}
	doc["tls_client_certificate_bound_access_tokens"] = true
	return doc, nil
}

// handleOpenIDConfiguration serves GET /.well-known/openid-configuration: the
// shared discovery document (see discoveryDocument). It wraps pkg/op's handler
// rather than serving s.idpCaps.OIDCProvider directly so the merged-in
// metadata appears.
func (s *Server) handleOpenIDConfiguration(w http.ResponseWriter, r *http.Request) {
	doc, err := s.discoveryDocument(r)
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
	writeJSON(w, http.StatusOK, doc)
}

// handleOAuthAuthServerMetadata serves GET /.well-known/oauth-authorization-server
// (RFC 8414). On top of the shared discovery document it advertises
// client_id_metadata_document_supported (draft-ietf-oauth-client-id-metadata-document
// §5): a URL client_id is resolved to a client metadata document on demand.
// pkg/op's DiscoveryConfiguration has no field for it, so it's merged into the
// map here. This is the one field the RFC 8414 document carries that
// /.well-known/openid-configuration does not — CIMD is RFC 8414 metadata, not
// OIDC discovery.
func (s *Server) handleOAuthAuthServerMetadata(w http.ResponseWriter, r *http.Request) {
	doc, err := s.discoveryDocument(r)
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
	doc["client_id_metadata_document_supported"] = true
	writeJSON(w, http.StatusOK, doc)
}

func (s *Server) handleHealth(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, map[string]string{
		"status": "ok",
		"commit": version.FullCommit,
	})
}

// handleSystemLogin authenticates an operator via a pre-shared break-glass key
// and returns a short-lived JWT for the system admin account.
func (s *Server) handleSystemLogin(w http.ResponseWriter, r *http.Request) {
	if s.idpCaps == nil || s.idpCaps.SystemLogin == nil || s.idpCaps.SystemJWT == nil {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "system login not available in this deployment mode"})
		return
	}

	header := r.Header.Get("Authorization")
	key, ok := strings.CutPrefix(header, "Bearer ")
	if !ok || key == "" {
		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "missing bearer token"})
		return
	}

	if !s.idpCaps.SystemLogin.ValidateKey(key) {
		slogutil.Warn(r.Context(), "system login: invalid key",
			slog.String("remote_addr", ratelimit.ClientIP(r)))
		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "invalid key"})
		return
	}

	acct, err := s.identity.ResolveHandle(r.Context(), "system", "admin")
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, fmt.Errorf("resolve system account: %w", err))
		return
	}

	token, err := s.idpCaps.SystemJWT.IssueLogin(r.Context(), authn.NewAuthIdentity(acct.ID, "admin", "system", "admin"), authn.LoginScopes)
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, fmt.Errorf("issue system jwt: %w", err))
		return
	}

	slogutil.Info(r.Context(), "system login: authenticated",
		slog.String("account_id", acct.ID.String()),
		slog.String("remote_addr", ratelimit.ClientIP(r)))

	resp := map[string]any{
		"token":      token,
		"expires_in": int(s.idpCaps.SystemJWT.TTL().Seconds()),
		"account_id": acct.ID.String(),
	}
	if s.idpCaps != nil && s.idpCaps.RefreshStore != nil {
		// Break-glass refresh isn't tied to an OAuth client — empty
		// issuer_client_id means /oauth/token won't accept it for refresh
		// (which is fine, break-glass refreshes via the bespoke endpoint).
		refreshToken, _, err := s.idpCaps.RefreshStore.CreateRefreshToken(r.Context(), acct.ID, authn.DefaultFamilyName("Break-glass"), "", authn.RefreshIdentity{})
		if err != nil {
			writeErr(w, r, http.StatusInternalServerError, fmt.Errorf("issue refresh token: %w", err))
			return
		}
		resp["refresh_token"] = refreshToken
	}
	writeJSON(w, http.StatusOK, resp)
}

// clearSessionCookie deletes the row backing the cookie's session ID (if
// present) and emits a Set-Cookie that expires the cookie. label distinguishes
// the warn log between console and IdP cookie failures.
func clearSessionCookie(w http.ResponseWriter, r *http.Request,
	cookie *authn.SessionCookie, store *authn.SessionStore, label string) {
	if cookie == nil || store == nil {
		return
	}
	if sessionID, ok := cookie.Read(r); ok {
		if err := store.Delete(r.Context(), sessionID); err != nil {
			slogutil.Warn(r.Context(), label+" session delete failed during logout",
				slog.String("error", err.Error()))
		}
	}
	cookie.Clear(w)
}

// revokeWorkOSSessionTimeout bounds the detached WorkOS HTTPS call so a
// degraded WorkOS endpoint can't pile up goroutines.
const revokeWorkOSSessionTimeout = 10 * time.Second

// revokeWorkOSSession looks up the current console session and, if it
// carries a WorkOS session id, asks WorkOS to revoke it server-side in a
// detached goroutine — the local session is authoritative for our app
// and the user's redirect must not block on a third-party round trip.
// Best-effort: failures are logged, never fatal.
func (s *Server) revokeWorkOSSession(r *http.Request) {
	if s.workos == nil || s.idpCaps == nil || s.idpCaps.ConsoleCookie == nil || s.idpCaps.ConsoleSessionStore == nil {
		return
	}
	sessionID, ok := s.idpCaps.ConsoleCookie.Read(r)
	if !ok {
		return
	}
	identity, err := s.idpCaps.ConsoleSessionStore.Lookup(r.Context(), sessionID)
	if err != nil || identity.WorkOSSessionID == "" {
		return
	}
	sid := identity.WorkOSSessionID
	bgCtx := context.WithoutCancel(r.Context())
	go func() {
		ctx, cancel := context.WithTimeout(bgCtx, revokeWorkOSSessionTimeout)
		defer cancel()
		if err := s.workos.RevokeSession(ctx, sid); err != nil {
			slogutil.Warn(ctx, "workos revoke session failed during logout",
				slog.String("error", err.Error()))
		}
	}()
}

// handleConsoleLogout terminates the console session and chains through
// the local IdP's /api/auth/end-session. For WorkOS-authed sessions it
// calls usermanagement.RevokeSession to end the WorkOS-side session;
// without that call the session lingers in the WorkOS dashboard until it
// expires on its own. The IdP owns its own session lifecycle.
func (s *Server) handleConsoleLogout(w http.ResponseWriter, r *http.Request) {
	s.revokeWorkOSSession(r)
	clearSessionCookie(w, r, s.idpCaps.ConsoleCookie, s.idpCaps.ConsoleSessionStore, "console")

	// returnTo always points at the console host; the end-session URL
	// itself lives on the auth host alongside the IdP session.
	returnTo := strings.TrimRight(s.consoleURL, "/") + "/logged-out"
	endSession, err := neturl.Parse(strings.TrimRight(s.authBaseURL, "/") + "/api/auth/end-session")
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, fmt.Errorf("build end-session url: %w", err))
		return
	}
	q := endSession.Query()
	q.Set("client_id", s.idpCaps.ConsoleClientID)
	q.Set("return_to", returnTo)
	endSession.RawQuery = q.Encode()

	http.Redirect(w, r, endSession.String(), http.StatusFound)
}

// handleEndSession terminates the IdP session for the calling browser.
// It always sets Max-Age=0 on all three browser cookies (__Host-login,
// __Host-refresh, idp_session) — even when the request carries none of
// them — so a half-cleared client ends up consistent. The idp row is
// deleted atomically with its (account_id, refresh_family_id), and
// the refresh family is revoked via RefreshStore.RevokeFamily before
// the response is written (best-effort: a revoke failure is logged
// but the cookies still clear and the redirect still happens — the
// user's intent is unambiguous).
//
// Validation of client_id + return_to gates only the redirect: an
// attacker who supplies a bogus return_to can still log themselves
// out, but cannot bounce the user to an attacker-controlled URI.
//
// COR-325. Pairs with COR-309's exchange gate: outstanding *exchanged*
// access tokens cannot be renewed because /oauth/token re-exchange
// consults the now-missing family, so they drain within their own TTL
// (5m repo/ops/debug, 8h api-access). The original login JWT itself
// is not revocation-gated at RP verification — see the FamilyID claim
// docstring in core/authn/jwt.go for the rationale — so a holder of
// the leaked login JWT can keep authenticating at RP-style endpoints
// until its 8h TTL expires. Full "log out everywhere" semantics
// require the cookie clear (this PR) plus an access-token-TTL drain.
func (s *Server) handleEndSession(w http.ResponseWriter, r *http.Request) {
	s.terminateIdpSession(r.Context(), r)
	s.clearAllSessionCookies(w)

	clientID := r.URL.Query().Get("client_id")
	returnTo := r.URL.Query().Get("return_to")

	if s.idpCaps == nil || s.idpCaps.ClientRegistry == nil || clientID == "" || returnTo == "" {
		s.serveLoggedOutFallback(w)
		return
	}
	client, ok := s.idpCaps.ClientRegistry.Lookup(clientID)
	if !ok || !client.AllowsPostLogoutRedirectURI(returnTo) {
		s.serveLoggedOutFallback(w)
		return
	}

	http.Redirect(w, r, returnTo, http.StatusFound)
}

// terminateIdpSession reads the idp_session cookie (if present),
// atomically deletes the backing row, and revokes the refresh family
// it was linked to. Best-effort: failures are logged with an
// `outcome` attribute so observability can alert on the case where
// cookies cleared but the refresh family is still alive — that's a
// real failure mode (the user thinks they're logged out but their
// refresh family lives until natural expiry, up to 30d). The
// user's intent to log out still wins at the cookie layer; the
// outcome attribute is the signal SRE relies on to detect when the
// downstream cleanup didn't.
func (s *Server) terminateIdpSession(ctx context.Context, r *http.Request) {
	if s.idpCaps == nil || s.idpCaps.IdpCookie == nil || s.idpCaps.IdpSessionStore == nil {
		return
	}
	sessionID, ok := s.idpCaps.IdpCookie.Read(r)
	if !ok {
		return
	}
	accountID, familyID, found, err := s.idpCaps.IdpSessionStore.DeleteAndReturnFamily(ctx, sessionID)
	if err != nil {
		slogutil.Warn(ctx, "idp session delete failed during logout",
			slog.String("outcome", "idp_delete_failed"),
			slog.String("error", err.Error()))
		return
	}
	if !found {
		// Idempotent logout — row was already gone. Nothing to revoke.
		return
	}
	if familyID == "" {
		// Fid-less idp session: the row was created via the
		// stripped-down fallback paths (handleProviderRegionalCallback
		// or the WorkOS callback) when the three-tier deps weren't
		// fully wired, or it's a pre-migration-015 row. No refresh
		// family was ever linked, so there's nothing to revoke. Info
		// rather than warn — this is a legitimate state, just not
		// the common one.
		slogutil.Info(ctx, "logout for fid-less session — skipping RevokeFamily",
			slog.String("outcome", "fid_less_skipped"),
			slog.String("account_id", accountID.String()),
			slog.String("session_id", sessionID))
		return
	}
	if s.idpCaps == nil || s.idpCaps.RefreshStore == nil {
		// Test fallback where no refresh store is wired.
		return
	}
	if err := s.idpCaps.RefreshStore.RevokeFamily(ctx, accountID, familyID); err != nil {
		if errors.Is(err, authn.ErrRefreshTokenNotFound) {
			// Idempotent: the family was already revoked elsewhere
			// (e.g. via /api/auth/tokens/current, an admin reset, or
			// natural expiry sweep). The cookies still clear and the
			// redirect still happens.
			return
		}
		slogutil.Warn(ctx, "refresh family revoke failed during logout — cookies still cleared, family may be alive until natural expiry",
			slog.String("outcome", "revoke_failed_cookies_cleared"),
			slog.String("error", err.Error()),
			slog.String("account_id", accountID.String()),
			slog.String("family_id", familyID))
	}
}

// clearAllSessionCookies sets Max-Age=0 on the three browser cookies
// COR-310 introduced (__Host-login, __Host-refresh) plus the existing
// idp_session cookie. Called unconditionally on end-session — a
// half-cleared client (some cookies kept, some deleted) ends up
// fully consistent on the next response either way.
func (s *Server) clearAllSessionCookies(w http.ResponseWriter) {
	if s.idpCaps == nil {
		return
	}
	if s.idpCaps.LoginCookie != nil {
		s.idpCaps.LoginCookie.Clear(w)
	}
	if s.idpCaps.RefreshCookie != nil {
		s.idpCaps.RefreshCookie.Clear(w)
	}
	if s.idpCaps.IdpCookie != nil {
		s.idpCaps.IdpCookie.Clear(w)
	}
}

// serveLoggedOutFallback writes a styled "you're signed out" body when the
// IdP cannot validate where to send the user. Self-contained (inline CSS,
// no external assets) so it still works if staticFS is broken. Links back
// to the configured console origin when one is set; on global hosts no
// single console exists, so the link is omitted there.
func (s *Server) serveLoggedOutFallback(w http.ResponseWriter) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.WriteHeader(http.StatusOK)
	var signInLink string
	if s.consoleURL != "" {
		href := html.EscapeString(strings.TrimRight(s.consoleURL, "/") + "/")
		signInLink = `<a class="btn" href="` + href + `">Sign in again</a>`
	}
	body := `<!doctype html><html lang="en"><head><meta charset="utf-8">` +
		`<meta name="viewport" content="width=device-width,initial-scale=1">` +
		`<title>Signed out — Entire</title><style>` +
		`body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;` +
		`background:#0d1117;color:#e6edf3;line-height:1.5;` +
		`display:flex;align-items:center;justify-content:center;height:100vh;margin:0}` +
		`.box{text-align:center;max-width:400px;padding:24px}` +
		`h1{font-size:24px;margin:0 0 12px}` +
		`p{color:#8b949e;margin:0 0 24px}` +
		`a.btn{display:inline-block;padding:10px 20px;background:#238636;color:#fff;` +
		`border-radius:6px;text-decoration:none;font-weight:500}` +
		`a.btn:hover{background:#2ea043}` +
		`</style></head><body><div class="box">` +
		`<h1>You're signed out.</h1>` +
		`<p>Both your console and identity-provider sessions have ended.</p>` +
		signInLink +
		`</div></body></html>`
	w.Write([]byte(body)) //nolint:errcheck,gosec // best-effort response write
}

// pkceCookieName returns the PKCE verifier cookie name. The prefix matches
// SessionCookie's scheme so PKCE and console_session share scope:
//   - secure=false → bare "pkce_verifier" (dev / localhost over HTTP).
//   - secure=true, hasDomain=false → "__Host-pkce_verifier" (host-only,
//     blocks sibling-subdomain injection of an unprefixed cookie).
//   - secure=true, hasDomain=true → "__Secure-pkce_verifier" (Domain-scoped,
//     follows the user across the auth↔console hop in a split deployment).
//     PKCE binds the verifier to the auth code at /api/auth/token, so a
//     sibling-subdomain attacker still can't redeem a code.
func pkceCookieName(secure, hasDomain bool) string {
	if !secure {
		return "pkce_verifier"
	}
	if hasDomain {
		return "__Secure-pkce_verifier"
	}
	return "__Host-pkce_verifier"
}

func isConsoleCookieSecure(c *authn.SessionCookie) bool {
	return c != nil && c.IsSecure()
}

func consoleCookieDomain(c *authn.SessionCookie) string {
	if c == nil {
		return ""
	}
	return c.Domain()
}

// clearPKCECookie removes the PKCE verifier cookie, matching the name+Domain
// scheme of the set site. Domain must match exactly — a Set-Cookie with the
// right name but wrong Domain leaves the original cookie behind.
func clearPKCECookie(w http.ResponseWriter, consoleCookie *authn.SessionCookie) {
	secure := isConsoleCookieSecure(consoleCookie)
	domain := consoleCookieDomain(consoleCookie)
	http.SetCookie(w, &http.Cookie{
		Name:     pkceCookieName(secure, domain != ""),
		Value:    "",
		Path:     "/",
		Domain:   domain,
		MaxAge:   -1,
		HttpOnly: true,
		Secure:   secure,
		SameSite: http.SameSiteLaxMode,
	})
}

// targetIsCLIAuth reports whether a validated login target points at the
// CLI device-flow approval page. The /cli/auth flow must run end-to-end on
// the auth host (where entire-core's device-grant store and host-only
// session cookie live), so callers branch on this to skip the bounce to
// PrimaryLoginURL and to route the OAuth callback to the auth host instead
// of the console host. Expects input that has already been through
// validateLoginTarget — i.e. a same-origin path, optionally with a query
// string.
func targetIsCLIAuth(target string) bool {
	path, _, _ := strings.Cut(target, "?")
	return path == "/cli/auth"
}

// loginHostFor returns the URL base where the OAuth /api/auth/login
// roundtrip runs for a given post-login target: the host that sets
// __Host-pkce_verifier, the host the callback fires on, and the host
// the final post-login redirect lands on. All three must agree, or the
// host-only verifier cookie is invisible to the callback and the token
// exchange fails on the PKCE check (RFC 7636 §4.6). /cli/auth lives on
// the auth host (device-grant store + session middleware gating POST
// /api/auth/cli/decision); everything else lives on the console host.
// Trailing slashes on the configured origins are normalised here so
// callers can concatenate "/api/auth/callback" directly without the
// risk of producing "//api/auth/callback" — pkg/op would reject it on
// the /oauth/token redirect_uri check (RFC 6749 §4.1.3 exact-match).
// Test that enforces this invariant: TestLoginRedirectURIMatchesHandlerHost.
func (s *Server) loginHostFor(target string) string {
	if targetIsCLIAuth(target) {
		return strings.TrimRight(s.authBaseURL, "/")
	}
	return strings.TrimRight(s.consoleURL, "/")
}

func validateLoginTarget(raw string) (string, error) {
	if raw == "" {
		return "/", nil
	}
	u, err := neturl.Parse(raw)
	if err != nil {
		return "", fmt.Errorf("parse target: %w", err)
	}
	if u.IsAbs() || u.Host != "" || !strings.HasPrefix(u.Path, "/") || strings.HasPrefix(u.Path, "//") ||
		strings.Contains(raw, `\`) || strings.Contains(u.Path, `\`) {
		return "", errors.New("target must be a same-origin path")
	}
	target := u.RequestURI()
	if target == "" {
		return "/", nil
	}
	return target, nil
}

func (s *Server) saveOAuthState(ctx context.Context, state, target string) error {
	return s.saveOAuthStateRecord(ctx, state, authn.OAuthStateRecord{RedirectTo: target})
}

func (s *Server) saveOAuthStateRecord(ctx context.Context, state string, rec authn.OAuthStateRecord) error {
	if s.oauthStateStore != nil {
		return s.oauthStateStore.Save(ctx, state, rec, oauthStateTTL)
	}

	now := time.Now()
	s.oauthMu.Lock()
	defer s.oauthMu.Unlock()
	for k, v := range s.oauthStates {
		if now.After(v.expiry) {
			delete(s.oauthStates, k)
		}
	}
	s.oauthStates[state] = oauthState{
		expiry:        now.Add(oauthStateTTL),
		payload:       rec.RedirectTo,
		provider:      rec.Provider,
		authRequestID: rec.AuthRequestID,
	}
	return nil
}

func (s *Server) lookupOAuthState(ctx context.Context, state string) (string, error) {
	rec, err := s.lookupOAuthStateRecord(ctx, state)
	if err != nil {
		return "", err
	}
	return rec.RedirectTo, nil
}

func (s *Server) lookupOAuthStateRecord(ctx context.Context, state string) (authn.OAuthStateRecord, error) {
	if s.oauthStateStore != nil {
		return s.oauthStateStore.Lookup(ctx, state)
	}

	s.oauthMu.Lock()
	defer s.oauthMu.Unlock()
	st, valid := s.oauthStates[state]
	if !valid || time.Now().After(st.expiry) {
		if valid {
			delete(s.oauthStates, state)
		}
		return authn.OAuthStateRecord{}, errors.New("invalid or expired oauth state")
	}
	return authn.OAuthStateRecord{RedirectTo: st.payload, Provider: st.provider, AuthRequestID: st.authRequestID}, nil
}

func (s *Server) consumeOAuthState(ctx context.Context, state string) (string, error) {
	rec, err := s.consumeOAuthStateRecord(ctx, state)
	if err != nil {
		return "", err
	}
	return rec.RedirectTo, nil
}

func (s *Server) consumeOAuthStateRecord(ctx context.Context, state string) (authn.OAuthStateRecord, error) {
	if s.oauthStateStore != nil {
		return s.oauthStateStore.Consume(ctx, state)
	}

	s.oauthMu.Lock()
	st, valid := s.oauthStates[state]
	delete(s.oauthStates, state)
	s.oauthMu.Unlock()
	if !valid || time.Now().After(st.expiry) {
		return authn.OAuthStateRecord{}, errors.New("invalid or expired oauth state")
	}
	return authn.OAuthStateRecord{RedirectTo: st.payload, Provider: st.provider, AuthRequestID: st.authRequestID}, nil
}

// redirectToPrimaryLogin bounces /api/auth/login hits that arrived on the
// auth host (or any host other than the console) to the configured
// front-door login URL. Returns true when it wrote a 302 — callers must
// stop processing on true. Returns false when no bounce is needed:
// PrimaryLoginURL unset, ConsoleURL unset/unparseable, or the request
// already arrived on the console host (the expected case).
func (s *Server) redirectToPrimaryLogin(w http.ResponseWriter, r *http.Request) bool {
	if s.primaryLoginURL == "" || s.consoleURL == "" {
		return false
	}
	consoleU, err := neturl.Parse(s.consoleURL)
	if err != nil || consoleU.Host == "" {
		return false
	}
	if r.Host == consoleU.Host {
		return false
	}
	http.Redirect(w, r, s.primaryLoginURL, http.StatusFound)
	return true
}

// handleConsoleLogin is the console's login entry point.
// It generates a PKCE code_verifier/code_challenge pair, stores the verifier
// in an HttpOnly cookie, and redirects to the authorize endpoint with the
// challenge. This prevents login CSRF — an attacker cannot complete the
// callback because they don't have the victim's code_verifier cookie.
//
// When called with ?request_id=<id>, this also serves as the bridge from
// pkg/op's /authorize entry point: pkg/op writes an op.AuthRequest, redirects
// here, and we either MarkDone (if the user already has an IdP session) and
// bounce to /authorize/callback, or stash the request_id in OAuth state and
// kick off the IdP login that finishes the request.
func (s *Server) handleConsoleLogin(w http.ResponseWriter, r *http.Request) {
	// pkg/op-bridged /authorize flows arrive here with a request_id. Handle
	// them before the primary-login redirect: the request_id flow is the
	// canonical OIDC entry point and must succeed regardless of which host
	// the request landed on.
	if requestID := r.URL.Query().Get("request_id"); requestID != "" {
		s.handleAuthRequestLogin(w, r, requestID)
		return
	}
	target, err := validateLoginTarget(r.URL.Query().Get("target"))
	if err != nil {
		slogutil.Warn(r.Context(), "invalid login target",
			slog.Bool("target_invalid", true),
			slog.Int("target_len", len(r.URL.Query().Get("target"))))
		http.Error(w, `{"error":"invalid target"}`, http.StatusBadRequest)
		return
	}
	// __Host-pkce_verifier set below is strictly host-scoped, and
	// handleAuthCallback (where it's read back) typically only runs on the
	// console host. If this entry was hit on the auth host for a regular
	// console target, the verifier would be stranded there and PKCE would
	// fail on /oauth/token — bounce out to the front-door login (e.g.
	// https://partial.to/login) instead. /cli/auth is the exception: that
	// flow has to land its session on the auth host (where the device-grant
	// store and the session middleware that gates POST /api/auth/cli/decision
	// live), so the bounce is skipped and the PKCE roundtrip runs locally.
	if !targetIsCLIAuth(target) && s.redirectToPrimaryLogin(w, r) {
		return
	}
	_, providerID, err := s.loginProviderFromQuery(r)
	if err != nil {
		http.Error(w, `{"error":"invalid provider"}`, http.StatusBadRequest)
		return
	}
	// Only an explicit ask is "requested" — persisting the registry default
	// here would later be recovered as an explicit ask at the request_id hop
	// below and defeat the WorkOS carve-out documented there (COR-1394).
	explicitProvider := explicitProviderRequested(r)

	verifier, challenge, err := authn.GeneratePKCE()
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}

	secure := isConsoleCookieSecure(s.idpCaps.ConsoleCookie)
	domain := consoleCookieDomain(s.idpCaps.ConsoleCookie)
	http.SetCookie(w, &http.Cookie{
		Name:     pkceCookieName(secure, domain != ""),
		Value:    verifier,
		Path:     "/",
		Domain:   domain,
		MaxAge:   600, // 10 minutes
		HttpOnly: true,
		Secure:   secure,
		SameSite: http.SameSiteLaxMode,
	})

	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
	rpState := hex.EncodeToString(b)
	rec := authn.OAuthStateRecord{RedirectTo: target}
	if explicitProvider {
		// Recovered by handleAuthRequestLogin at the request_id hop, whose
		// query pkg/op's LoginURL strips down to request_id alone
		// (oidcop/client.go) — this is the only place the requested provider
		// can ride across that bounce (COR-1394).
		rec.Provider = providerID
	}
	if err := s.saveOAuthStateRecord(r.Context(), rpState, rec); err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}

	// redirect_uri host comes from loginHostFor — must match the host that
	// served this handler (where __Host-pkce_verifier was just set) and the
	// host handleAuthCallback uses for both expectedRedirectURI and the
	// final post-login redirect. If any of those disagree the verifier
	// cookie is unreadable on callback and PKCE fails. loginHostFor
	// trims any trailing slash on the configured origin so we don't
	// produce "//api/auth/callback" here.
	redirectURI := s.loginHostFor(target) + "/api/auth/callback"
	q := neturl.Values{}
	q.Set("client_id", s.idpCaps.ConsoleClientID)
	q.Set("redirect_uri", redirectURI)
	q.Set("state", rpState)
	q.Set("code_challenge", challenge)
	q.Set("code_challenge_method", "S256")
	q.Set("response_type", "code")
	q.Set("scope", "openid")
	q.Set("provider", providerID)
	// /api/auth/login may land on the console host (split deployment);
	// /authorize must run on the auth host so pkg/op writes the auth
	// request and bounces back to /api/auth/login?request_id=, which
	// handleAuthRequestLogin picks up to run the IdP roundtrip.
	http.Redirect(w, r, strings.TrimRight(s.authBaseURL, "/")+"/authorize?"+q.Encode(), http.StatusFound)
}

// handleAuthRequestLogin bridges pkg/op's /authorize redirect to our IdP
// session flow. The request body already lives in auth_requests (pkg/op called
// Storage.CreateAuthRequest before redirecting); our job is to authenticate
// the user, MarkDone the request, and hand control back to pkg/op via
// /authorize/callback so it can issue the auth code.
func (s *Server) handleAuthRequestLogin(w http.ResponseWriter, r *http.Request, requestID string) {
	if s.idpCaps == nil {
		http.Error(w, `{"error":"oidc bridging not configured"}`, http.StatusServiceUnavailable)
		return
	}
	ar, err := s.idpCaps.AuthRequestStore.ByID(r.Context(), requestID)
	if err != nil {
		http.Error(w, `{"error":"invalid or expired request_id"}`, http.StatusBadRequest)
		return
	}
	provider, providerID, err := s.loginProviderFromQuery(r)
	if err != nil {
		http.Error(w, `{"error":"invalid provider"}`, http.StatusBadRequest)
		return
	}

	// A provider match is only enforced against the IdP session when the
	// caller explicitly asked for one. With neither ?provider= nor ?method=
	// in the query, loginProviderFromQuery falls back to the registry default
	// — and the WorkOS SSO return path builds its return_to without a
	// provider param on purpose, so treating the default as "requested" would
	// force a re-auth through GitHub and wipe the WorkOS binding the user
	// just established. Absent an explicit ask, any active session is fine.
	explicitProvider := explicitProviderRequested(r)

	// pkg/op's LoginURL carries only request_id (oidcop/client.go), so an
	// explicit ask made on the ORIGINAL /api/auth/login hit never survives
	// this bounce in the query string (COR-1394). Recover it from the
	// oauth-state record saved at that hop — keyed by the RP state, which
	// also rides pkg/op's own AuthRequest (ar.State) and so is recoverable.
	// Looked up, not consumed: handleAuthCallback still needs this record.
	// Not found for a caller that reaches /authorize directly without going
	// through handleConsoleLogin first (e.g. the CLI's own login page), which
	// degrades to today's defaulted behavior unchanged.
	if !explicitProvider {
		rec, lookupErr := s.lookupOAuthStateRecord(r.Context(), ar.State)
		switch {
		case lookupErr != nil:
			// Expected and high-volume (expired, or any caller that never went
			// through handleConsoleLogin — CLI, WorkOS return), so this is a
			// rate signal rather than a Warn: the store doesn't distinguish
			// "no such state" from "expired" from a transient backend error,
			// and logging every miss at Warn would drown in that traffic.
			metrics.OAuthStateProviderRecoveryMiss(r.Context())
		case rec.Provider != "":
			if recovered, lookupErr := s.lookupProvider(rec.Provider); lookupErr == nil {
				provider, providerID, explicitProvider = recovered, rec.Provider, true
			} else {
				// The record names a provider the registry no longer has (e.g.
				// reconfigured between the two hops) — log it rather than
				// silently resolving to the default, the wrong-IdP shape this
				// fix exists to close.
				slogutil.Warn(r.Context(), "recovered oauth-state provider not in registry",
					slog.String("provider", rec.Provider), slog.String("error", lookupErr.Error()))
			}
		}
	}

	// If the user already has an IdP session, short-circuit the provider
	// roundtrip: MarkDone immediately and let pkg/op issue the code. An
	// explicit prompt=login (ar.RequestsReauth) skips the short-circuit so the
	// provider round-trip re-runs and re-seeds the GitHub token; every other
	// /authorize caller omits prompt and keeps the short-circuit.
	//
	// Before trusting the cached account_id, confirm it still resolves to
	// an account row. The session can outlive its account when the user
	// was deleted (here or in a sibling region using the shared global
	// pool) and then re-signed up — the new handle row points at a fresh
	// account_id, but our cached idp_session still carries the tombstone.
	// Stamping that tombstone onto the auth_request loops the user
	// through /api/me's 401-and-clear (see handleMe at the ErrNotFound
	// branch). Drop the stale row and fall through to a real provider
	// round-trip so loginFlow.FromProviderProfile resolves the live id.
	if !ar.RequestsReauth() && s.idpCaps.IdpCookie != nil && s.idpCaps.IdpSessionStore != nil {
		if sessionID, ok := s.idpCaps.IdpCookie.Read(r); ok {
			cached, err := s.idpCaps.IdpSessionStore.Lookup(r.Context(), sessionID)
			switch {
			case err != nil:
				slogutil.Warn(r.Context(), "IdP session lookup failed in oidc bridging login", slog.String("error", err.Error()))
				s.idpCaps.IdpCookie.Clear(w)
			default:
				// An explicitly requested provider must match the session's,
				// or the issued JWT would carry the session's provider (and
				// its org binding, or lack of one) rather than the one the
				// caller asked to authenticate with. Fall through to the real
				// round-trip instead of marking the request done with the
				// wrong identity.
				if explicitProvider && cached.Provider != providerID {
					slogutil.Info(r.Context(), "IdP session provider mismatch; re-authenticating",
						slog.String("session_provider", cached.Provider),
						slog.String("requested_provider", providerID))
					break
				}
				if _, err := s.identity.GetAccount(r.Context(), cached.AccountID); err != nil {
					if errors.Is(err, identity.ErrNotFound) {
						clearSessionCookie(w, r, s.idpCaps.IdpCookie, s.idpCaps.IdpSessionStore, "idp")
						break
					}
					writeErr(w, r, http.StatusInternalServerError, err)
					return
				}
				// Only short-circuit a GitHub session that still holds a valid
				// refresh token; otherwise fall through so the GitHub roundtrip
				// re-runs and maybeSeedGitHubTokens reseeds. A non-github session
				// (mock/other provider) has no github token to seed and keeps the
				// unconditional short-circuit, as does any deployment without the
				// github-tokens service wired.
				if cached.Provider == "github" && s.githubTokens != nil {
					valid, err := s.githubTokens.HasValidRefreshToken(r.Context(), cached.AccountID)
					if err != nil {
						writeErr(w, r, http.StatusInternalServerError, err)
						return
					}
					if !valid {
						break
					}
				}
				scopes := authn.FilterClientControlledScopes(ar.Scopes, s.resolveLoginScopes(r.Context(), cached.AccountID.String()))
				if err := s.idpCaps.AuthRequestStore.MarkDone(r.Context(), requestID, cached.ToAuthRequestIdentity(), time.Now(), scopes); err != nil {
					writeErr(w, r, http.StatusInternalServerError, err)
					return
				}
				http.Redirect(w, r, "/authorize/callback?id="+neturl.QueryEscape(requestID), http.StatusFound)
				return
			}
		}
	}

	// No session — drive the configured provider's OAuth flow. The provider
	// callback reads AuthRequestID off the state and finishes the bridge.
	state, err := randomHex(16)
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
	rec := authn.OAuthStateRecord{Provider: providerID, AuthRequestID: requestID}
	if err := s.saveOAuthStateRecord(r.Context(), state, rec); err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
	url, err := provider.AuthCodeURL(state, authn.AuthModeLogin)
	if err != nil {
		writeErr(w, r, http.StatusServiceUnavailable, err)
		return
	}
	http.Redirect(w, r, url, http.StatusFound)
}

// handleAuthCallback exchanges an authorization code for a console session.
// This is the RP (console) side of the back-channel exchange — it calls the
// IdP's /api/auth/token over HTTPS rather than reading the auth-code store
// directly. The RP needs no DB access to the auth-code table; trust is
// mediated by the client_id/secret handshake.
func (s *Server) handleAuthCallback(w http.ResponseWriter, r *http.Request) {
	if s.idpCaps == nil {
		http.Error(w, `{"error":"session auth not configured"}`, http.StatusServiceUnavailable)
		return
	}

	code := r.URL.Query().Get("code")
	if code == "" {
		http.Error(w, `{"error":"missing code"}`, http.StatusBadRequest)
		return
	}

	rpState := r.URL.Query().Get("state")
	if rpState == "" {
		slogutil.Warn(r.Context(), "oauth callback missing state")
		clearPKCECookie(w, s.idpCaps.ConsoleCookie)
		http.Error(w, `{"error":"missing state"}`, http.StatusBadRequest)
		return
	}
	targetPayload, err := s.lookupOAuthState(r.Context(), rpState)
	if err != nil {
		metrics.OAuthStateMiss(r.Context())
		slogutil.Warn(r.Context(), "oauth callback state lookup failed", slog.String("error", err.Error()))
		clearPKCECookie(w, s.idpCaps.ConsoleCookie)
		http.Error(w, `{"error":"invalid or expired state"}`, http.StatusBadRequest)
		return
	}
	target, err := validateLoginTarget(targetPayload)
	if err != nil {
		slogutil.Error(r.Context(), "stored oauth target failed validation",
			slog.String("state", rpState),
			slog.Bool("target_invalid", true),
			slog.Int("target_len", len(targetPayload)))
		clearPKCECookie(w, s.idpCaps.ConsoleCookie)
		http.Error(w, `{"error":"invalid target"}`, http.StatusBadRequest)
		return
	}

	// Read PKCE code_verifier from cookie. Must use the same name scheme the
	// login entry used (pkceCookieName) — otherwise an attacker who can set
	// cookies on a sibling subdomain could inject an unprefixed `pkce_verifier`
	// that we'd naively read. Missing cookie is logged so operators can
	// correlate "invalid or expired code" responses with cookie eviction.
	cookieName := pkceCookieName(isConsoleCookieSecure(s.idpCaps.ConsoleCookie), consoleCookieDomain(s.idpCaps.ConsoleCookie) != "")
	var codeVerifier string
	if cookie, err := r.Cookie(cookieName); err == nil {
		codeVerifier = cookie.Value
	} else {
		slogutil.Info(r.Context(), "pkce_verifier cookie missing in callback",
			slog.String("error", err.Error()))
	}

	// The redirect_uri presented to /oauth/token must match exactly what
	// handleConsoleLogin sent on /authorize — pkg/op verifies them per
	// RFC 6749 §4.1.3. loginHostFor gives the same answer on both sides
	// (/cli/auth → auth host, everything else → console host) and
	// normalises trailing slashes, so the string match is exact.
	callbackBase := s.loginHostFor(target)
	expectedRedirectURI := callbackBase + "/api/auth/callback"
	identity, err := s.idpCaps.TokenEndpointClient.ExchangeCode(r.Context(), code, expectedRedirectURI, codeVerifier)
	if err != nil {
		var exchangeErr *TokenExchangeError
		switch {
		case errors.As(err, &exchangeErr):
			slogutil.Info(r.Context(), "token exchange failed",
				slog.Int("status", exchangeErr.Status),
				slog.String("oauth_error", exchangeErr.OAuthError),
				slog.String("description", exchangeErr.Description))
			if exchangeErr.Status >= 500 {
				// Retryable IdP-side fault (DB blip, transaction retry, proxy). The
				// code was NOT consumed — preserve pkce_verifier so the user's
				// retry with the same code can still complete once the IdP recovers.
				// Destroying the cookie here would turn every transient 5xx into
				// a forced login restart, which is exploitable as a targeted DoS.
				writeErr(w, r, http.StatusBadGateway, err)
			} else {
				// Definitive failure (invalid_grant, PKCE fail, etc.) — the code is
				// no longer usable, so the verifier has no value either.
				clearPKCECookie(w, s.idpCaps.ConsoleCookie)
				http.Error(w, `{"error":"invalid or expired code"}`, http.StatusBadRequest)
			}
		default:
			// Transport error — IdP unreachable. Surface 502 and keep the cookie
			// so a retry can succeed once connectivity restores.
			writeErr(w, r, http.StatusBadGateway, err)
		}
		return
	}

	consumedTarget, err := s.consumeOAuthState(r.Context(), rpState)
	if err != nil {
		metrics.OAuthStateMiss(r.Context())
		slogutil.Warn(r.Context(), "oauth callback state consume failed", slog.String("error", err.Error()))
		clearPKCECookie(w, s.idpCaps.ConsoleCookie)
		http.Error(w, `{"error":"invalid or expired state"}`, http.StatusBadRequest)
		return
	}
	if consumedTarget != targetPayload {
		slogutil.Error(r.Context(), "oauth callback state changed between lookup and consume",
			slog.String("state", rpState),
			slog.Int("lookup_target_len", len(targetPayload)),
			slog.Int("consumed_target_len", len(consumedTarget)))
		clearPKCECookie(w, s.idpCaps.ConsoleCookie)
		http.Error(w, `{"error":"invalid target"}`, http.StatusBadRequest)
		return
	}

	// Success — the code was consumed, so the verifier is no longer useful.
	clearPKCECookie(w, s.idpCaps.ConsoleCookie)

	sessionID, err := s.idpCaps.ConsoleSessionStore.Create(r.Context(), identity)
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
	s.idpCaps.ConsoleCookie.Set(w, sessionID)

	// console_session was Set-Cookie'd host-only on whichever host served
	// this handler. /cli/auth flows ran on the auth host (callbackBase
	// resolved to s.authBaseURL above); everything else ran on the console
	// host. Land the browser back on the same origin so the SPA's first
	// request carries the freshly-set cookie.
	http.Redirect(w, r, callbackBase+target, http.StatusFound)
}

// handleRegionalProviderLoginRedirect is the regional binding for
// GET /api/auth/{provider}/login: it just bounces to the session-issuing
// /api/auth/login endpoint. The zero-scope routing OAuth dance
// (handleRouterProviderLogin) is global-only.
func (s *Server) handleRegionalProviderLoginRedirect(w http.ResponseWriter, r *http.Request) {
	providerID := r.PathValue("provider")
	if _, err := s.lookupProvider(providerID); err != nil {
		http.Error(w, "unknown auth provider", http.StatusNotFound)
		return
	}
	http.Redirect(w, r, "/api/auth/login?provider="+neturl.QueryEscape(providerID), http.StatusFound)
}

// handleRouterProviderLogin is the global binding for
// GET /api/auth/{provider}/login: zero-scope "routing OAuth" that identifies
// the caller without minting a session, so the global host can hand them
// back to their home jurisdiction.
func (s *Server) handleRouterProviderLogin(w http.ResponseWriter, r *http.Request) {
	providerID := r.PathValue("provider")
	provider, err := s.lookupProvider(providerID)
	if err != nil {
		http.Error(w, "unknown auth provider", http.StatusNotFound)
		return
	}

	state, err := randomHex(16)
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
	if s.oauthStateStore != nil {
		if err := s.oauthStateStore.Save(r.Context(), state, authn.OAuthStateRecord{Provider: providerID}, 10*time.Minute); err != nil {
			writeErr(w, r, http.StatusInternalServerError, err)
			return
		}
	} else {
		s.oauthMu.Lock()
		s.oauthStates[state] = oauthState{
			expiry:   time.Now().Add(10 * time.Minute),
			provider: providerID,
		}
		s.oauthMu.Unlock()
	}
	url, err := provider.AuthCodeURL(state, authn.AuthModeRouting)
	if err != nil {
		writeErr(w, r, http.StatusServiceUnavailable, err)
		return
	}
	http.Redirect(w, r, url, http.StatusFound)
}

func (s *Server) handleProviderGlobalCallback(w http.ResponseWriter, r *http.Request) {
	provider, providerID, ok := s.callbackProvider(w, r)
	if !ok {
		return
	}
	// Two different situations hide behind a single error= parameter, and a CLI
	// dispatch wants opposite handling for each:
	//
	//   - access_denied: the user pressed Cancel on GitHub's consent screen.
	//     Forwarding them to a regional /authorize would hand them another
	//     login they just refused, so this dead-ends for every action.
	//   - anything else (server_error, temporarily_unavailable, ...): GitHub is
	//     broken. That is the identify-leg failure the cli_authorize soft-fail
	//     exists for — same shape as the ExchangeCode failure below (ENT-1061)
	//     — so geo-dispatch rather than dead-end a client with no way back.
	//
	// The state is peeked, not consumed: no code is exchanged on this leg, so
	// the row lapses on its own TTL.
	if errParam := r.URL.Query().Get("error"); errParam != "" {
		cause := fmt.Errorf("provider authorization failed: %s", errParam)
		if errParam != "access_denied" {
			action := s.peekGlobalOAuthAction(r.Context(), r.URL.Query().Get("state"))
			if s.dispatchCLIAuthorizeFallback(w, r, action, cause) {
				return
			}
		}
		writeAuthErrorPage(w, r, cause)
		return
	}
	code := r.URL.Query().Get("code")
	state := r.URL.Query().Get("state")
	if code == "" || state == "" {
		http.Error(w, "missing code or state", http.StatusBadRequest)
		return
	}
	statePayload, ok := s.consumeProviderOAuthState(w, r, state, providerID)
	if !ok {
		return
	}
	action := decodeGlobalOAuthAction(statePayload)
	if s.cookie != nil {
		if _, hasCookie := s.cookie.Read(r); hasCookie {
			metrics.CookieAutoRedirectSkipped(r.Context())
		}
	}
	// A CLI /authorize dispatch has no way back from an error page, so each
	// identify-leg failure below soft-fails to the geo jurisdiction instead
	// (dispatchCLIAuthorizeFallback); every other action keeps its rendering.
	tokens, err := provider.ExchangeCode(r.Context(), code)
	if err != nil {
		if s.dispatchCLIAuthorizeFallback(w, r, action, err) {
			return
		}
		// Browser leg: a GitHub-side exchange failure must not 502, or Cloudflare
		// dead-ends the user with its branded page (ENT-1061). Render our own
		// non-5xx error page instead.
		writeAuthErrorPage(w, r, err)
		return
	}
	profile, err := provider.FetchPublicProfile(r.Context(), tokens.AccessToken)
	if err != nil {
		if s.dispatchCLIAuthorizeFallback(w, r, action, err) {
			return
		}
		writeAuthErrorPage(w, r, err)
		return
	}
	homeJurisdiction, err := s.routerCaps.Router.HandleCallback(r.Context(), model.HandleProvider(providerID), profile.ProviderUserID, profile.Login)
	if err != nil {
		if s.dispatchCLIAuthorizeFallback(w, r, action, err) {
			return
		}
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
	if homeJurisdiction != "" && s.cookie != nil {
		if cookieRegion, hasCookie := s.cookie.Read(r); !hasCookie || cookieRegion != homeJurisdiction {
			s.cookie.Set(w, homeJurisdiction)
		}
	}
	geoJurisdiction := authn.GeoSuggestJurisdiction(
		r.Header.Get("Cf-Ipcountry"), r.Header.Get("Cf-Ipcontinent"), s.jurisdictionAuthHosts)
	redirectURL := s.resolveGlobalCallbackRedirect(r.Context(), homeJurisdiction, geoJurisdiction, action)
	if redirectURL == "" {
		// No completion target: a known user with no handback context and no BFF
		// login-start configured, or a new user in a degenerate config with no
		// live geo region (ENT-1058: never redirect to a region /api/auth/login
		// URL, and never http.Redirect to an empty Location).
		writeAuthErrorPage(w, r, errors.New("jurisdiction login unavailable"))
		return
	}
	http.Redirect(w, r, redirectURL, http.StatusFound)
}

func (s *Server) handleProviderRegionalCallback(w http.ResponseWriter, r *http.Request) {
	provider, providerID, ok := s.callbackProvider(w, r)
	if !ok {
		return
	}
	if errParam := r.URL.Query().Get("error"); errParam != "" {
		http.Error(w, "authorization failed: "+errParam, http.StatusBadRequest)
		return
	}
	code := r.URL.Query().Get("code")
	state := r.URL.Query().Get("state")
	if code == "" || state == "" {
		http.Error(w, "missing code or state", http.StatusBadRequest)
		return
	}
	stateRec, ok := s.consumeProviderOAuthStateRecord(w, r, state, providerID)
	if !ok {
		return
	}

	if stateRec.AuthRequestID == "" {
		slogutil.Warn(r.Context(), "oauth state missing auth_request_id", slog.String("state", state))
		http.Error(w, "invalid or expired state", http.StatusBadRequest)
		return
	}

	tokens, err := provider.ExchangeCode(r.Context(), code)
	if err != nil {
		// Browser leg: a GitHub-side exchange failure must not 502, or Cloudflare
		// dead-ends the user with its branded page (ENT-1061). Bounce back to the
		// OIDC client's registered redirect_uri with error=access_denied so the
		// browser lands on the client's styled login-error UX.
		s.redirectAuthError(w, r, stateRec.AuthRequestID, err)
		return
	}
	profile, err := provider.FetchPublicProfile(r.Context(), tokens.AccessToken)
	if err != nil {
		s.redirectAuthError(w, r, stateRec.AuthRequestID, err)
		return
	}
	result, err := s.idpCaps.LoginFlow.FromProviderProfile(r.Context(), profile, ratelimit.ClientIP(r))
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
	s.emitGitHubHandleCreated(r.Context(), result)
	// github_user_tokens is global (COR-932), so a foreign-cell login seeds the
	// same shared row the user's home cell reads — there's no per-region PII
	// boundary on this table any more, and skipping the seed here would leave a
	// user who only ever logs in at a foreign cell permanently unlinked.
	s.maybeSeedGitHubTokens(r.Context(), providerID, result.AccountID, profile, tokens)
	// Waitlist GitHub-org bypass: if this still-unapproved account's login is an
	// active member of a hard-coded org, admit it asynchronously (COR-503
	// amendment). No-op for approved/non-github accounts and when the feature is
	// off; best-effort, off the login hot path.
	s.maybeBypassWaitlistForOrg(r.Context(), result)
	if s.cookie != nil && result.HomeJurisdiction != "" {
		s.cookie.Set(w, result.HomeJurisdiction)
	}
	identity, err := result.AuthIdentity()
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
	// Resolved once and reused below: both the cookie login JWT and the auth-
	// request completion derive from the same login scopes, so a single
	// SpiceDB platform-admin check (inside resolveLoginScopes) suffices.
	loginScopes := s.resolveLoginScopes(r.Context(), identity.AccountID.String())
	if s.canEstablishBrowserSession() {
		// A user can log in and use APIs from any jurisdiction regardless of
		// home, so home and foreign logins alike get the full local browser
		// session — the refresh family lives in whichever region handled the
		// login. "Foreign" governs only the PII boundary above
		// (maybeSeedGitHubTokens), not session establishment. (Cross-juris
		// token *widening* — using this session at another region's resources —
		// is the separate fid-less foreign-session exchange, not this path.)
		if err := s.establishBrowserSession(r.Context(), w, identity, loginScopes); err != nil {
			writeErr(w, r, http.StatusInternalServerError, err)
			return
		}
	} else if s.idpCaps != nil && s.idpCaps.IdpSessionStore != nil && s.idpCaps.IdpCookie != nil {
		// Browser-session deps not wired (stripped-down mode): keep a plain idp
		// session so SSO still works.
		sessionID, err := s.idpCaps.IdpSessionStore.Create(r.Context(), identity)
		if err != nil {
			writeErr(w, r, http.StatusInternalServerError, err)
			return
		}
		s.idpCaps.IdpCookie.Set(w, sessionID)
	}

	if s.idpCaps == nil {
		writeErr(w, r, http.StatusInternalServerError, errors.New("auth request store not configured"))
		return
	}
	ar, err := s.idpCaps.AuthRequestStore.ByID(r.Context(), stateRec.AuthRequestID)
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, fmt.Errorf("load auth request: %w", err))
		return
	}
	scopes := authn.FilterClientControlledScopes(ar.Scopes, loginScopes)
	if err := s.idpCaps.AuthRequestStore.MarkDone(r.Context(), stateRec.AuthRequestID, identity.ToAuthRequestIdentity(), time.Now(), scopes); err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
	http.Redirect(w, r, "/authorize/callback?id="+neturl.QueryEscape(stateRec.AuthRequestID), http.StatusFound)
}

// canEstablishBrowserSession reports whether every dependency the three-tier
// browser session needs is wired. Browser login falls back to a plain idp
// session when any is missing (e.g. a stripped-down mode), rather than 500ing.
func (s *Server) canEstablishBrowserSession() bool {
	return s.idpCaps != nil &&
		s.idpCaps.IdpSessionStore != nil && s.idpCaps.IdpCookie != nil &&
		s.idpCaps.LoginCookie != nil && s.idpCaps.RefreshCookie != nil &&
		s.idpCaps.RefreshStore != nil && s.idpCaps.JWT != nil
}

// establishBrowserSession mints a refresh-token family and a login JWT bound
// to it, links a fresh idp session to that family, and sets the three browser
// cookies: __Host-login (login JWT, 8h), __Host-refresh (opaque entr_, 7d),
// and the idp SSO cookie. It is the browser arm of the three-tier session
// model (ADR 20260527); the caller resolves scopes (this method does no
// authz). The OAuth-callback caller (handleProviderRegionalCallback) gates on
// home jurisdiction so roaming sessions stay fid-less; the org-SSO caller is
// in-region by construction. The family id is persisted on idp_sessions, so
// logout/revocation (COR-325) reads it back rather than this returning it.
//
// Order is issue → persist idp session → persist refresh family → set cookies.
// The login JWT signs first (no DB write); cookies emit only after both rows
// commit, so a persistence failure never leaves the browser holding cookies
// for a session that doesn't exist. The idp session is written before the
// refresh family deliberately: if the family write fails, the orphan is an
// unreferenced idp session (no cookie points at it, so it's never looked up and
// expires at its TTL) — not a phantom family listed in GET /api/auth/tokens.
func (s *Server) establishBrowserSession(ctx context.Context, w http.ResponseWriter, identity authn.AuthIdentity, scopes []authn.Scope) error {
	familyID := authn.NewFamilyID()

	loginJWT, err := s.idpCaps.JWT.IssueLoginWithFamily(ctx, identity, scopes, familyID)
	if err != nil {
		return fmt.Errorf("issue login jwt: %w", err)
	}
	sessionID, err := s.idpCaps.IdpSessionStore.CreateWithRefreshFamily(ctx, identity, familyID)
	if err != nil {
		return fmt.Errorf("create idp session: %w", err)
	}
	refreshToken, err := s.idpCaps.RefreshStore.CreateRefreshTokenInFamily(
		ctx, identity.AccountID, familyID,
		authn.DefaultFamilyName("Console login"), s.idpCaps.ConsoleClientID, authn.BrowserRefreshTokenTTL,
		identity.ToRefreshIdentity())
	if err != nil {
		return fmt.Errorf("create refresh family: %w", err)
	}

	s.idpCaps.LoginCookie.Set(w, loginJWT)
	s.idpCaps.RefreshCookie.Set(w, refreshToken)
	s.idpCaps.IdpCookie.Set(w, sessionID)
	return nil
}

func (s *Server) handleProviderExchange(w http.ResponseWriter, r *http.Request) {
	provider, _, ok := s.callbackProvider(w, r)
	if !ok {
		return
	}
	if !provider.DirectExchangeEnabled() {
		http.Error(w, `{"error":"direct exchange not supported"}`, http.StatusMethodNotAllowed)
		return
	}
	var req struct {
		AccessToken string `json:"access_token"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || req.AccessToken == "" {
		http.Error(w, `{"error":"provide access_token"}`, http.StatusBadRequest)
		return
	}
	profile, err := provider.FetchPublicProfile(r.Context(), req.AccessToken)
	if err != nil {
		writeErr(w, r, http.StatusUnauthorized, err)
		return
	}
	result, err := s.idpCaps.LoginFlow.FromProviderProfile(r.Context(), profile, ratelimit.ClientIP(r))
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
	s.emitGitHubHandleCreated(r.Context(), result)
	if result.IsForeignJurisdiction {
		s.writeWrongJurisdiction(r.Context(), w, result.HomeJurisdiction, r.PathValue("provider"))
		return
	}
	if s.cookie != nil && result.HomeJurisdiction != "" {
		s.cookie.Set(w, result.HomeJurisdiction)
	}
	status := http.StatusOK
	if result.IsNew {
		status = http.StatusCreated
	}
	writeJSON(w, status, result)
}

func (s *Server) handleProviderDevice(w http.ResponseWriter, r *http.Request) {
	provider, _, ok := s.callbackProvider(w, r)
	if !ok {
		return
	}
	deviceProvider, ok := provider.(authn.DeviceProvider)
	if !ok {
		http.Error(w, `{"error":"device flow not supported"}`, http.StatusMethodNotAllowed)
		return
	}
	dcr, err := deviceProvider.RequestDeviceCode(r.Context())
	if err != nil {
		writeErr(w, r, http.StatusBadGateway, err)
		return
	}
	if dcr.VerificationURIComplete == "" && dcr.VerificationURI != "" && dcr.UserCode != "" {
		dcr.VerificationURIComplete = dcr.VerificationURI + "?user_code=" + neturl.QueryEscape(dcr.UserCode)
	}
	writeJSON(w, http.StatusOK, dcr)
}

func (s *Server) handleProviderPoll(w http.ResponseWriter, r *http.Request) {
	provider, _, ok := s.callbackProvider(w, r)
	if !ok {
		return
	}
	deviceProvider, ok := provider.(authn.DeviceProvider)
	if !ok {
		http.Error(w, `{"error":"device flow not supported"}`, http.StatusMethodNotAllowed)
		return
	}
	var req struct {
		DeviceCode string `json:"device_code"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || req.DeviceCode == "" {
		http.Error(w, `{"error":"provide device_code"}`, http.StatusBadRequest)
		return
	}
	tokens, _, err := deviceProvider.ExchangeDeviceCode(r.Context(), req.DeviceCode)
	if err != nil {
		writeErr(w, r, http.StatusBadGateway, err)
		return
	}
	if tokens == nil {
		writeJSON(w, http.StatusOK, map[string]string{"status": "pending"})
		return
	}
	profile, err := provider.FetchPublicProfile(r.Context(), tokens.AccessToken)
	if err != nil {
		writeErr(w, r, http.StatusBadGateway, err)
		return
	}
	result, err := s.idpCaps.LoginFlow.FromProviderProfile(r.Context(), profile, ratelimit.ClientIP(r))
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
	s.emitGitHubHandleCreated(r.Context(), result)
	providerID := r.PathValue("provider")
	if result.IsForeignJurisdiction {
		s.writeWrongJurisdiction(r.Context(), w, result.HomeJurisdiction, providerID)
		return
	}
	s.maybeSeedGitHubTokens(r.Context(), providerID, result.AccountID, profile, tokens)
	// Waitlist GitHub-org bypass: if this still-unapproved account's login is an
	// active member of a hard-coded org, admit it asynchronously (COR-503
	// amendment). No-op for approved/non-github accounts and when the feature is
	// off; best-effort, off the login hot path.
	s.maybeBypassWaitlistForOrg(r.Context(), result)
	if s.cookie != nil && result.HomeJurisdiction != "" {
		s.cookie.Set(w, result.HomeJurisdiction)
	}
	status := http.StatusOK
	if result.IsNew {
		status = http.StatusCreated
	}
	writeJSON(w, status, result)
}

func (s *Server) callbackProvider(w http.ResponseWriter, r *http.Request) (authn.OAuthProvider, string, bool) {
	providerID := r.PathValue("provider")
	provider, err := s.lookupProvider(providerID)
	if err != nil {
		http.Error(w, "unknown auth provider", http.StatusNotFound)
		return nil, "", false
	}
	return provider, providerID, true
}

func (s *Server) consumeProviderOAuthState(w http.ResponseWriter, r *http.Request, state, providerID string) (string, bool) {
	rec, ok := s.consumeProviderOAuthStateRecord(w, r, state, providerID)
	if !ok {
		return "", false
	}
	return rec.RedirectTo, true
}

func (s *Server) consumeProviderOAuthStateRecord(w http.ResponseWriter, r *http.Request, state, providerID string) (authn.OAuthStateRecord, bool) {
	rec, err := s.consumeOAuthStateRecord(r.Context(), state)
	if err != nil {
		if s.oauthStateStore != nil {
			metrics.OAuthStateMiss(r.Context())
		}
		http.Error(w, "invalid or expired state", http.StatusBadRequest)
		return authn.OAuthStateRecord{}, false
	}
	if rec.Provider != "" && rec.Provider != providerID {
		http.Error(w, "invalid or expired state", http.StatusBadRequest)
		return authn.OAuthStateRecord{}, false
	}
	return rec, true
}

func randomHex(n int) (string, error) {
	b := make([]byte, n)
	if _, err := rand.Read(b); err != nil {
		return "", fmt.Errorf("generate random: %w", err)
	}
	return hex.EncodeToString(b), nil
}

// noEdgeCache wraps a handler with Cache-Control: no-cache so Cloudflare (or any
// CDN that caches by file extension) revalidates with origin on every request
// instead of pinning a stale /admin/main.js for hours after a deploy. The SPA
// shell is small, ETag/Last-Modified still let unchanged files 304 quickly,
// and HTML-by-default semantics don't apply to .js/.css under default CDN
// rules — so without this header the admin SPA went stale until we manually
// purged the edge cache. Apply to the whole static catch-all so adding a new
// asset can never reintroduce the bug.
func noEdgeCache(h http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Cache-Control", "no-cache")
		h.ServeHTTP(w, r)
	})
}

// noDirListing wraps h so that requests resolving to a directory without an
// index.html return 404 instead of http.FileServer's auto-generated listing.
// The root "/" is handled by the more specific GET /{$} route
// (handleConsoleRoot), so it no longer depends on a staticFS index.html.
func noDirListing(fsys fs.FS, h http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		p := strings.Trim(r.URL.Path, "/")
		if p == "" {
			p = "."
		}
		if info, err := fs.Stat(fsys, p); err == nil && info.IsDir() {
			if _, err := fs.Stat(fsys, path.Join(p, "index.html")); err != nil {
				http.NotFound(w, r)
				return
			}
		}
		h.ServeHTTP(w, r)
	})
}

// handleGlobalRoot serves the bare global-host root. The global core is a
// browser-only router, not a destination, so it 302s to the main site (the
// origin of ENTIRE_LOGIN_START_URL) when configured. If unset (e.g. local dev)
// it falls back to the static landing page so there's no dead end. ENT-1058.
func (s *Server) handleGlobalRoot(w http.ResponseWriter, r *http.Request) {
	if origin := s.loginStartOrigin(); origin != "" {
		http.Redirect(w, r, origin, http.StatusFound)
		return
	}
	serveStaticFile("global-landing.html")(w, r)
}

// serveStaticFile returns a handler that serves a single file from staticFS.
// Content-Type is derived from the filename extension (text/html for .html,
// image/svg+xml for .svg, etc.) so this works for any asset embedded in the
// static tree, not just HTML pages. Unknown extensions fall back to
// text/html — every existing caller serves an html file so the behavior is
// unchanged there.
func serveStaticFile(name string) http.HandlerFunc {
	contentType := mime.TypeByExtension(path.Ext(name))
	if contentType == "" {
		contentType = "text/html; charset=utf-8"
	}
	return func(w http.ResponseWriter, _ *http.Request) {
		data, err := fs.ReadFile(staticFS, name)
		if err != nil {
			http.Error(w, "page not found", http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", contentType)
		w.Write(data) //nolint:errcheck,gosec // best-effort response write
	}
}

// resolveGlobalCallbackRedirect picks the post-OAuth redirect target. It never
// returns a region /api/auth/login URL (ENT-1058); "" means the caller renders
// the inline auth error page.
//
// When the OAuth action is resolve_jurisdiction, the handed-back jurisdiction
// is the known user's home region, or — for a new user (homeJurisdiction ==
// "") — the caller's Cloudflare-geo best guess (geoJurisdiction). Both are
// unsigned routing hints by design; the regional login re-validates. An empty
// geo guess (no live fallback region — a degenerate config) yields "". If the
// return_to can't be honoured (not allowlisted, or the redirect build fails),
// this soft-fails to the BFF login-start bounce rather than a region login
// URL — the bounce may itself be "" if login-start isn't configured.
//
// When the OAuth action is cli_authorize, the target is the chosen
// jurisdiction's /authorize with the CLI's original query replayed verbatim —
// home region for a known user, geo guess otherwise. Both come out of
// jurisdictionAuthHosts, which errOnPartialJurisdictionAuthHosts guarantees is
// complete relative to REGION_HOSTS. See core/api/global_oidc_dispatch.go.
//
// When the OAuth action is a debug-bounce and the home region is known, the
// target is rewritten to the regional /api/authz/debug-bounce so the cluster
// JWT issue can complete. New users fall through to the default handling
// below — they're definitionally not platform admins, so the regional handler
// would 403 them anyway. Misconfigured JurisdictionHosts bounces to the BFF
// login-start.
//
// For every other case (non-resolve, non-debug-bounce action — the direct
// global login entry), a known user bounces to the BFF login-start; a new
// user bounces to the BFF login-start pinned to the geo guess, which routes
// straight to that region's /authorize (account creation, waitlist-gated) —
// exactly what a region-picker submission used to produce, minus the page.
//
// Uses jurisdictionHosts (the REGION_HOSTS console map), NOT jurisdictionAuthHosts.
// Despite the /api/authz/ prefix, debug-bounce is functionally a console-host
// endpoint: it reads the console_session cookie. That cookie is host-only on
// the console host, and the host names are siblings under partial.to so no
// Domain attribute can bridge auth.* and console.* without leaking into
// customer clusters. Routing the browser to the console host is the only
// option that keeps the cookie visible.
func (s *Server) resolveGlobalCallbackRedirect(ctx context.Context, homeJurisdiction, geoJurisdiction string, action globalOAuthAction) string {
	if action.Action == oauthActionResolveJurisdiction {
		// Known user: hand home back to the RP. New user: hand back the geo
		// best guess.
		jurisdiction := homeJurisdiction
		if jurisdiction == "" {
			jurisdiction = geoJurisdiction
			if jurisdiction != "" {
				slogutil.Info(ctx, "resolve-jurisdiction: new user, geo-routed",
					slog.String("jurisdiction", jurisdiction))
			}
		}
		if jurisdiction == "" {
			// No home and no live geo region: nothing to hand back. NOT the
			// login-start bounce — that restarts the resolve flow and would
			// redirect-loop on a config this degenerate.
			slogutil.Warn(ctx, "resolve-jurisdiction: no jurisdiction to hand back (no live geo region)")
			return ""
		}
		if err := validateReturnTo(action.ReturnTo, s.handoffReturnToHosts); err != nil {
			slogutil.Warn(ctx, "resolve-jurisdiction: return_to not allowlisted; bouncing", slog.Any("error", err))
			return s.loginStartBounceURL()
		}
		dest, err := buildHandoffRedirect(action.ReturnTo, action.State, jurisdiction)
		if err != nil {
			slogutil.Warn(ctx, "resolve-jurisdiction: build redirect failed", slog.Any("error", err))
			return s.loginStartBounceURL()
		}
		return dest
	}
	if action.Action == oauthActionCLIAuthorize {
		// Known user: their recorded home, which Router.HandleCallback has
		// already validated against this same map — so a non-empty home always
		// resolves and needs no drift fallback here. New user: the geo guess.
		// "" only when no live jurisdiction exists at all, which renders the
		// auth error page.
		if homeJurisdiction != "" {
			return s.jurisdictionAuthorizeURL(homeJurisdiction, action.AuthorizeQuery)
		}
		return s.jurisdictionAuthorizeURL(geoJurisdiction, action.AuthorizeQuery)
	}
	if action.Action == oauthActionDebugBounce && homeJurisdiction != "" {
		regionURL := s.jurisdictionHosts[homeJurisdiction]
		if regionURL == "" {
			slogutil.Warn(ctx, "debug-bounce: no region URL for jurisdiction; bouncing to BFF login-start",
				slog.String("home_jurisdiction", homeJurisdiction))
			return s.loginStartBounceURL()
		}
		return regionalDebugBounceURL(regionURL, action.Cluster, action.ReturnTo)
	}
	// Default / non-resolve / debug-bounce-without-home: a known user with no
	// handback context bounces to the BFF login-start (ENT-1058). A new user
	// bounces to the BFF login-start pinned to the geo guess, so the BFF PKCEs
	// /authorize against that region directly (which creates the account
	// regionally, waitlist-gated).
	if homeJurisdiction != "" {
		return s.loginStartBounceURL()
	}
	if geoJurisdiction != "" {
		return s.loginStartWithJurisdiction(geoJurisdiction)
	}
	return ""
}

// emitGitHubHandleCreated fires resource_lifecycle_v1.github_handle.created for
// a brand-new GitHub signup (COR-678) — the signal that drives /me author
// attribution in entire-api. Best-effort and self-attributed: the new account
// is both actor and resource. The event carries the GitHub id+login so a
// consumer derives the no-reply email without re-querying GitHub. No-op for an
// existing account or a non-GitHub provider.
func (s *Server) emitGitHubHandleCreated(ctx context.Context, result *loginflow.Result) {
	if result == nil || !result.IsNew || result.Provider != "github" {
		return
	}
	s.LifecycleEvents().Publish(ctx, resourceevents.TypeGitHubHandle,
		result.AccountID, resourceevents.OpCreated, result.AccountID,
		resourceevents.WithGitHubIdentity(result.ProviderUserID, result.Handle),
		resourceevents.WithJurisdiction(result.HomeJurisdiction))
}

// loginStartOrigin returns scheme://host of the configured BFF login-start
// URL (path/query stripped), or "" if unset/unparseable.
func (s *Server) loginStartOrigin() string {
	if s.loginStartURL == "" {
		return ""
	}
	u, err := neturl.Parse(s.loginStartURL)
	if err != nil || u.Scheme == "" || u.Host == "" {
		return ""
	}
	return u.Scheme + "://" + u.Host
}

// loginStartBounceURL returns the BFF login-start URL with jurisdictional=1
// set (to restart the jurisdictional flow), or "" if unset/unparseable.
func (s *Server) loginStartBounceURL() string {
	if s.loginStartURL == "" {
		return ""
	}
	u, err := neturl.Parse(s.loginStartURL)
	if err != nil || u.Scheme == "" || u.Host == "" {
		return ""
	}
	q := u.Query()
	q.Set("jurisdictional", "1")
	u.RawQuery = q.Encode()
	return u.String()
}

// loginStartWithJurisdiction returns the BFF login-start URL with an explicit
// jurisdiction set, so the BFF routes straight to that region's /authorize
// (its explicit-?jurisdiction= branch) rather than re-running region resolution.
// Used to complete a new user's direct global login with their geo-resolved
// jurisdiction. Returns "" if the login-start URL is unset/unparseable.
func (s *Server) loginStartWithJurisdiction(jurisdiction string) string {
	if s.loginStartURL == "" {
		return ""
	}
	u, err := neturl.Parse(s.loginStartURL)
	if err != nil || u.Scheme == "" || u.Host == "" {
		return ""
	}
	q := u.Query()
	q.Set("jurisdiction", jurisdiction)
	u.RawQuery = q.Encode()
	return u.String()
}

// repoTokenLookupError is the structured failure shape resolveRepoTokenTarget
// returns; writeRepoTokenErr translates it to the matching HTTP response.
type repoTokenLookupError struct {
	status int
	body   string
}

func (e *repoTokenLookupError) Error() string { return e.body }

func newRepoTokenLookupErr(status int, body string) *repoTokenLookupError {
	return &repoTokenLookupError{status: status, body: body}
}

// resolveCreateClusterSlug resolves the destination cluster for a new repo.
// One regional core serves every cluster in its jurisdiction (royalcanin and
// purina both run on the US regional core), so the slug is per-request:
//
//   - explicit selector (req.cluster_slug): pinned by the caller, validated
//     against the cluster registry to refuse typos and decommissioned slugs.
//   - empty selector: fall back to the jurisdiction's default cluster
//     (cluster.is_default=true, exactly one per jurisdiction).
//
// Returns ErrNotFound when an explicit slug doesn't match any active cluster
// in this jurisdiction, or when no default is configured for the jurisdiction.
// s.jurCaps being nil is a 503 — operationally distinct from "no such slug."
func (s *Server) resolveCreateClusterSlug(ctx context.Context, requested string) (string, int, error) {
	if s.jurCaps == nil {
		return "", http.StatusServiceUnavailable, errors.New("cluster registry not configured")
	}
	if requested != "" {
		c, err := s.cluster.GetBySlug(ctx, s.jurisdiction, requested)
		if err != nil {
			if errors.Is(err, cluster.ErrNotFound) {
				return "", http.StatusBadRequest, fmt.Errorf("unknown cluster_slug %q in jurisdiction %q", requested, s.jurisdiction)
			}
			return "", http.StatusInternalServerError, fmt.Errorf("resolve cluster slug: %w", err)
		}
		// Hidden only affects listing visibility, not placement: a caller
		// who knows a hidden cluster's slug may still pin repos to it.
		return c.Slug, 0, nil
	}
	c, err := s.cluster.GetDefault(ctx, s.jurisdiction)
	if err != nil {
		if errors.Is(err, cluster.ErrNotFound) {
			return "", http.StatusInternalServerError, fmt.Errorf("no default cluster configured for jurisdiction %q", s.jurisdiction)
		}
		return "", http.StatusInternalServerError, fmt.Errorf("resolve default cluster: %w", err)
	}
	return c.Slug, 0, nil
}

// resolveCreateClusterByHost mirrors resolveCreateClusterSlug but selects the
// destination cluster by its public host — the user-facing identifier the
// /api/v1 surface speaks — instead of its internal slug. An empty host falls
// back to the jurisdiction default. Returns the resolved cluster so callers
// read both its slug (internal routing) and public host (client response).
func (s *Server) resolveCreateClusterByHost(ctx context.Context, requestedHost string) (*cluster.Cluster, int, error) {
	if s.jurCaps == nil {
		return nil, http.StatusServiceUnavailable, errors.New("cluster registry not configured")
	}
	if requestedHost != "" {
		c, err := s.cluster.GetByPublicHost(ctx, requestedHost)
		if err != nil {
			if errors.Is(err, cluster.ErrNotFound) {
				return nil, http.StatusBadRequest, fmt.Errorf("unknown cluster host %q", requestedHost)
			}
			return nil, http.StatusInternalServerError, fmt.Errorf("resolve cluster host: %w", err)
		}
		// GetByPublicHost isn't jurisdiction-scoped; preserve the same
		// "create lands in this core's jurisdiction" guarantee the slug
		// resolver gets for free from GetBySlug.
		if c.Jurisdiction != s.jurisdiction {
			return nil, http.StatusBadRequest, fmt.Errorf("cluster host %q is in jurisdiction %q, not %q", requestedHost, c.Jurisdiction, s.jurisdiction)
		}
		// Hidden only affects listing visibility, not placement: a caller
		// who knows a hidden cluster's host may still pin repos to it (mirror
		// placement has always worked this way, see resolveClusterHost).
		return c, 0, nil
	}
	c, err := s.cluster.GetDefault(ctx, s.jurisdiction)
	if err != nil {
		if errors.Is(err, cluster.ErrNotFound) {
			return nil, http.StatusInternalServerError, fmt.Errorf("no default cluster configured for jurisdiction %q", s.jurisdiction)
		}
		return nil, http.StatusInternalServerError, fmt.Errorf("resolve default cluster: %w", err)
	}
	return c, 0, nil
}

// resolveClusterHostJurisdiction maps a CLI-typed data-plane host to the
// jurisdiction of the cluster serving it. Empty or unknown host is a
// 400-level error: the STS mirror lookup contract requires the caller to
// commit to a jurisdiction so we never accidentally pick the wrong same-URL
// mirror across regions. The cluster registry being unconfigured (s.jurCaps
// nil) is a 503 — operationally distinct from "you sent a bad host."
func (s *Server) resolveClusterHostJurisdiction(ctx context.Context, host string) (string, error) {
	if host == "" {
		return "", newRepoTokenLookupErr(http.StatusBadRequest, `{"error":"cluster_host is required for mirror lookups"}`)
	}
	if s.jurCaps == nil {
		return "", newRepoTokenLookupErr(http.StatusServiceUnavailable, `{"error":"cluster registry not configured"}`)
	}
	c, err := s.cluster.GetByPublicHost(ctx, host)
	if err != nil {
		if errors.Is(err, cluster.ErrNotFound) {
			return "", newRepoTokenLookupErr(http.StatusBadRequest, `{"error":"unknown cluster_host"}`)
		}
		return "", fmt.Errorf("resolve cluster host: %w", err)
	}
	return c.Jurisdiction, nil
}

// checkPlatformAdmin resolves the admin_read permission (admin ∪
// admin_reader) on the singleton platform resource and returns the HTTP
// status the caller should respond with: (200, nil) on success, (503, err)
// when SpiceDB is unreachable, or (403, nil) when the account holds neither
// admin tier. It backs the non-authoritative capability gates — login /
// cookie-session ops-access scope and the admin SPA bundle — which
// deliberately admit read-only admins; the issued ops-access token is then
// narrowed to scope=admin:read at exchange time, and every write RPC
// re-checks admin_write live. Distinct from requirePlatformAdmin
// (admin_handlers.go), which gates mutations on full admin and writes the
// response itself.
func (s *Server) checkPlatformAdmin(ctx context.Context, accountID string) (int, error) {
	allowed, err := s.authz.Can(ctx, "account:"+accountID, "admin_read", "platform:"+PlatformResourceID)
	if err != nil {
		return http.StatusServiceUnavailable, fmt.Errorf("authz check: %w", err)
	}
	if !allowed {
		return http.StatusForbidden, nil
	}
	return http.StatusOK, nil
}

// resolveLoginScopes returns the entire:* scope set a login JWT for accountID
// should carry. Calls SpiceDB to test platform-admin and includes
// entire:ops-access only when the test passes. SpiceDB-unreachable degrades to
// the non-admin set rather than failing login — losing the ability to exchange
// for an ops-access token is preferable to keeping operators locked out, and
// the user can re-login once SpiceDB recovers.
func (s *Server) resolveLoginScopes(ctx context.Context, accountID string) []authn.Scope {
	status, err := s.checkPlatformAdmin(ctx, accountID)
	if err != nil {
		slogutil.Warn(ctx, "login scope resolution: platform-admin check failed; granting non-admin scopes",
			slog.String("account_id", accountID),
			slog.String("error", err.Error()))
		return authn.LoginScopesFor(false)
	}
	return authn.LoginScopesFor(status == http.StatusOK)
}

// checkBackupAdmin gates the login-JWT branch of the backup-access STS
// exchange. Parallels checkPlatformAdmin but resolves the
// backup_admin_access permission, not the backup_admin relation
// directly. The wrapping is intentional: it lets the permission expand
// later (e.g. `permission backup_admin_access = backup_admin + restore_admin`)
// without touching call sites. checkPlatformAdmin's direct-relation
// check predates this convention; do not collapse them without an ADR.
//
// By schema design backup_admin_access does NOT flow from platform#admin
// — explicit platform#backup_admin grant required. See
// core/authz/schema.go for the strict-separation rationale.
//
// Returns the same (status, err) shape: (200, nil) on success,
// (503, err) when SpiceDB is unreachable, (403, nil) when not granted.
func (s *Server) checkBackupAdmin(ctx context.Context, accountID string) (int, error) {
	allowed, err := s.authz.Can(ctx, "account:"+accountID, "backup_admin_access", "platform:"+PlatformResourceID)
	if err != nil {
		return http.StatusServiceUnavailable, fmt.Errorf("authz check: %w", err)
	}
	if !allowed {
		return http.StatusForbidden, nil
	}
	return http.StatusOK, nil
}

// lookupRepoLocalOrGlobal returns the repo when it lives in this regional
// plane (full data, isForeign=false), and falls back to the global
// repo_registry otherwise (partial data — ID, Name, ClusterSlug —
// populated; state/mirror/provision-* zero-valued; isForeign true).
// resource.ErrNotFound surfaces a true miss.
func (s *Server) lookupRepoLocalOrGlobal(ctx context.Context, repoID model.RepoID) (*model.Repo, string, bool, error) {
	repo, err := s.regional.GetRepo(ctx, repoID)
	if err == nil {
		// A regional hit is by definition homed here; a jurisdiction-agnostic
		// core (global) has no region of its own to claim, so the
		// jurisdiction degrades to "" exactly like the pre-field wire shape.
		return repo, s.jurisdiction, false, nil
	}
	if !errors.Is(err, regional.ErrNotFound) {
		return nil, "", false, fmt.Errorf("regional get repo: %w", err)
	}
	reg, err := s.resource.GetRepoRegistration(ctx, repoID)
	if err != nil {
		// errors.Is still sees resource.ErrNotFound through %w; wrapping
		// keeps the discriminator intact and satisfies wrapcheck.
		return nil, "", false, fmt.Errorf("get repo registration: %w", err)
	}
	return &model.Repo{
		ID:          reg.ID,
		Name:        reg.Name,
		ClusterSlug: reg.ClusterSlug,
	}, reg.Jurisdiction, true, nil
}

// usersSorts whitelists the sort keys the Users tab may request, each mapped
// to a safe SQL ORDER BY fragment. "handle" sorts on the LEFT JOINed primary
// handle. Anything else falls back to the default (newest-first by creation).
var usersSorts = map[string]string{
	"created":  "a.created_at",
	"handle":   "h.handle",
	"approved": "a.approved",
}

func (s *Server) handleAdminUsers(w http.ResponseWriter, r *http.Request) {
	if !s.requirePlatformAdminRead(w, r) {
		return
	}

	p := ParseListParams(r, usersSorts)

	// ?status= filters the waitlist server-side: "pending" -> unapproved only,
	// "approved" -> approved only, absent/anything else -> all.
	var approved *bool
	switch r.URL.Query().Get("status") {
	case "pending":
		no := false
		approved = &no
	case "approved":
		yes := true
		approved = &yes
	}

	page, err := s.identity.ListAccountsPage(r.Context(), identity.AccountQuery{
		Search:   p.Q,
		OrderBy:  p.OrderClause(usersSorts, "created"),
		Approved: approved,
		Limit:    p.Limit,
		Offset:   p.Offset,
	})
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}

	// Attach handles for just this page's accounts (one batched query),
	// rather than the whole table. Blocker accounts ride in the same batch so
	// the UI can show WHO blocked a row without a second round-trip.
	ids := make([]model.AccountID, 0, len(page.Items))
	for _, a := range page.Items {
		ids = append(ids, a.ID)
		if a.BlockedBy != nil {
			ids = append(ids, *a.BlockedBy)
		}
	}
	handlesByAccount, err := s.identity.ListHandlesForAccounts(r.Context(), ids)
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}

	type userEntry struct {
		AccountID             string          `json:"account_id"`
		HomeJurisdiction      string          `json:"home_jurisdiction"`
		Handles               []*model.Handle `json:"handles"`
		Approved              bool            `json:"approved"`
		ApprovedAt            *time.Time      `json:"approved_at,omitempty"`
		BlockedAt             *time.Time      `json:"blocked_at,omitempty"`
		BlockedBy             string          `json:"blocked_by,omitempty"`
		BlockedByHandle       string          `json:"blocked_by_handle,omitempty"`
		OnboardingCompletedAt *time.Time      `json:"onboarding_completed_at,omitempty"`
		CreatedAt             time.Time       `json:"created_at"`
	}
	users := make([]userEntry, len(page.Items))
	for i, a := range page.Items {
		users[i] = userEntry{
			AccountID:             a.ID.String(),
			HomeJurisdiction:      a.HomeJurisdiction,
			Handles:               handlesByAccount[a.ID],
			Approved:              a.Approved,
			ApprovedAt:            a.ApprovedAt,
			BlockedAt:             a.BlockedAt,
			OnboardingCompletedAt: a.OnboardingCompletedAt,
			CreatedAt:             a.CreatedAt,
		}
		if a.BlockedBy != nil {
			users[i].BlockedBy = a.BlockedBy.String()
			// Best-effort attribution: an erased blocker account has no handles
			// left, so the UI falls back to the raw account ID.
			users[i].BlockedByHandle = primaryQualifiedHandle(handlesByAccount[*a.BlockedBy])
		}
	}

	writeJSON(w, http.StatusOK, NewListResponse(users, page.Total, p))
}

var accountDeletionSorts = map[string]string{
	"requested": "a.deletion_requested_at",
	"created":   "a.created_at",
}

// handleAdminAccountDeletionRequests lists accounts with a pending deletion for
// the admin console. Each row's status is derived: "blocked" when the account
// still owns an org (the reaper skips it regardless of the clock), else
// "pending" while inside the cooldown, else "eligible" (cooldown elapsed,
// awaiting the next reaper pass). Erased accounts are gone from `accounts`, so
// this view only shows in-flight requests, never completed erasures.
func (s *Server) handleAdminAccountDeletionRequests(w http.ResponseWriter, r *http.Request) {
	if !s.requirePlatformAdminRead(w, r) {
		return
	}

	p := ParseListParams(r, accountDeletionSorts)

	page, err := s.identity.ListAccountsPage(r.Context(), identity.AccountQuery{
		Search:              p.Q,
		OrderBy:             p.OrderClause(accountDeletionSorts, "requested"),
		PendingDeletionOnly: true,
		Limit:               p.Limit,
		Offset:              p.Offset,
	})
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}

	ids := make([]model.AccountID, len(page.Items))
	for i, a := range page.Items {
		ids[i] = a.ID
	}
	handlesByAccount, err := s.identity.ListHandlesForAccounts(r.Context(), ids)
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}

	now := time.Now().UTC()
	type deletionEntry struct {
		AccountID        string          `json:"account_id"`
		HomeJurisdiction string          `json:"home_jurisdiction"`
		Handles          []*model.Handle `json:"handles"`
		RequestedAt      *time.Time      `json:"requested_at,omitempty"`
		CooldownEndsAt   *time.Time      `json:"cooldown_ends_at,omitempty"`
		Status           string          `json:"status"`          // pending | eligible | blocked
		BlockedByOrgs    int             `json:"blocked_by_orgs"` // owned orgs preventing the reap
	}
	entries := make([]deletionEntry, len(page.Items))
	for i, a := range page.Items {
		handles := handlesByAccount[a.ID]
		if handles == nil {
			handles = []*model.Handle{} // serialize [] not null
		}
		e := deletionEntry{
			AccountID:        a.ID.String(),
			HomeJurisdiction: a.HomeJurisdiction,
			Handles:          handles,
			RequestedAt:      a.DeletionRequestedAt,
		}
		if a.DeletionRequestedAt != nil {
			ends := a.DeletionRequestedAt.Add(AccountDeletionCooldown)
			e.CooldownEndsAt = &ends
			// "blocked" takes precedence over the clock: the reaper skips an
			// account that still owns an org, so it never reaps regardless of
			// how long the cooldown has elapsed. A single row's owned-org lookup
			// failing degrades that row to "unknown" rather than failing the
			// whole page.
			switch ownedOrgs, oerr := s.resource.ListOwnedOrgsForAccount(r.Context(), a.ID); {
			case oerr != nil:
				slogutil.Warn(r.Context(), "admin deletion-requests: owned-org lookup failed",
					slog.String("account_id", a.ID.String()), slog.Any("error", oerr))
				e.Status = "unknown"
			case len(ownedOrgs) > 0:
				e.Status, e.BlockedByOrgs = "blocked", len(ownedOrgs)
			case now.Before(ends):
				e.Status = "pending"
			default:
				e.Status = "eligible"
			}
		}
		entries[i] = e
	}

	writeJSON(w, http.StatusOK, NewListResponse(entries, page.Total, p))
}

