		http.Error(w, `{"error":"provide token"}`, http.StatusBadRequest)
		return
	}
	authzRequested := req.Action != "" || req.ResourceType != "" || req.ResourceID != ""
	if authzRequested && (req.Action == "" || req.ResourceType == "" || req.ResourceID == "") {
		http.Error(w, `{"error":"provide action, resource_type, and resource_id together"}`, http.StatusBadRequest)
		return
