package api

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"net/url"
	"strings"
	"time"

	"entire.io/core/githubapp"
	"entire.io/core/githubgraphql"
	"entire.io/core/githubperms/githubapi"
	"entire.io/core/mirrorrepo"
	"entire.io/core/mirrorrequest"
	"entire.io/core/model"
	"entire.io/core/permssnapshotter"
	"entire.io/core/regional"
)

const (
	mirrorRequestRepoInaccessibleFailureCode = "repo_inaccessible"
	mirrorRequestGitHubLinkFailureCode       = "github_link_required"
	mirrorRequestSourceTooLargeFailureCode   = "source_too_large"
	mirrorRequestGitHubFailureCode           = "github_unavailable"
	mirrorRequestConflictFailureCode         = "mirror_conflict"
	mirrorRequestPlacementDeletedFailureCode = "placement_deleted"
	mirrorURLConflictFailureCode             = "mirror_url_conflict"
	mirrorNameConflictFailureCode            = "mirror_name_conflict"
	mirrorRequestInvalidFailureCode          = "invalid_request"
	mirrorRequestInternalFailureCode         = "internal"
)

const (
	mirrorRequestRepoInaccessibleMessage  = "cannot mirror this repository: it may not exist, the Entire App may not be installed with access to it, or you may not have read access"
	mirrorRequestGitHubLinkMessage        = "link your GitHub account and submit a new request"
	mirrorRequestGitHubUnavailableMessage = "GitHub is temporarily unavailable; retry later"
	mirrorRequestConflictMessage          = "another mirror placement already claims this repository on the selected cluster"
	mirrorRequestPlacementDeletedMessage  = "the mirror placement was deleted while this request was processing"
	mirrorRequestInternalMessage          = "mirror request could not be completed"
)

// MirrorRequestError describes how a persisted mirror request failed.
type MirrorRequestError struct {
	Code      string
	Message   string
	Retryable bool
	cause     error
}

func (f *MirrorRequestError) Error() string {
	if f.cause == nil {
		return f.Message
	}
	return fmt.Sprintf("%s: %v", f.Message, f.cause)
}
func (f *MirrorRequestError) Unwrap() error { return f.cause }

// CreateRequestedMirror validates a persisted request and creates its mirror placement.
func (s *Server) CreateRequestedMirror(ctx context.Context, request mirrorrequest.Request) (model.RepoID, *MirrorRequestError) {
	var zero model.RepoID
	owner, repo, failure := validateMirrorRequest(request)
	if failure != nil {
		return zero, failure
	}

	clusterHost, publicURL, failure := s.resolveMirrorRequestCluster(ctx, request)
	if failure != nil {
		return zero, failure
	}

	currentGitHubUserID, status, err := s.requireGitHubUser(ctx, request.AccountID)
	if err != nil {
		if status == http.StatusUnauthorized {
			return zero, &MirrorRequestError{Code: mirrorRequestGitHubLinkFailureCode, Message: mirrorRequestGitHubLinkMessage}
		}
		return zero, InternalMirrorRequestFailure(fmt.Errorf("resolve linked GitHub identity: %w", err))
	}
	if currentGitHubUserID != request.GitHubUserID {
		return zero, &MirrorRequestError{
			Code:    mirrorRequestGitHubLinkFailureCode,
			Message: "the GitHub account linked to this request has changed; link the original account and submit a new request",
		}
	}

	switch {
	case s.mirrorRepos == nil:
		return zero, InternalMirrorRequestFailure(errors.New("mirror service not configured"))
	case s.repoBridge == nil:
		return zero, InternalMirrorRequestFailure(errors.New("data plane bridge not configured"))
	case s.githubPerms == nil:
		return zero, InternalMirrorRequestFailure(errors.New("github permissions service not configured"))
	case s.ghAppCaps == nil || s.ghAppCaps.Bootstrapper == nil:
		return zero, InternalMirrorRequestFailure(errors.New("mirror bootstrapper not configured"))
	}

	githubRepoID, isPrivate, ownerLogin, repoName, defaultBranch, err := s.ghAppCaps.Bootstrapper.EnsureRepoKnown(ctx, owner, repo, time.Now())
	if err != nil {
		return zero, mirrorRequestBootstrapFailure(err)
	}

	projectOwner, seedRole, operationErr := s.authorizeUserMirrorCreate(ctx, request.AccountID, request.GitHubUserID, owner, repo)
	if operationErr != nil {
		return zero, mirrorRequestOperationFailure(operationErr)
	}
	sizeBytes, err := s.mirrorSourceSize(ctx, githubRepoID, ownerLogin, repoName)
	if err != nil {
		return zero, mirrorRequestSourceFailure(err)
	}
	if sizeBytes >= maxMirrorSourceDiskUsageBytes {
		tooLarge := mirrorSourceTooLargeError(sizeBytes)
		return zero, &MirrorRequestError{Code: mirrorRequestSourceTooLargeFailureCode, Message: tooLarge.Message}
	}

	seed := &regional.SeedGrant{
		GranteeType: "account",
		GranteeID:   model.ID(request.AccountID.String()),
		Role:        seedRole,
	}
	result, err := s.finishMirrorPlacement(ctx, mirrorPlacementInput{
		owner: owner, repo: repo,
		ownerLogin: ownerLogin, repoName: repoName,
		clusterHost: clusterHost, clusterSlug: request.ClusterSlug,
		jurisdiction: request.Jurisdiction, publicURL: publicURL,
		githubRepoID: githubRepoID, isPrivate: isPrivate, defaultBranch: defaultBranch,
		projectOwner: projectOwner, creatorSeed: seed, actorID: request.AccountID,
		reservedMirrorID: request.MirrorID,
	})
	if err != nil {
		return zero, mirrorRequestPlacementFailure(err)
	}
	mirrorID, err := model.ParseRepoID(result.MirrorID)
	if err != nil {
		return zero, InternalMirrorRequestFailure(fmt.Errorf("parse created mirror ID: %w", err))
	}

	if operationErr := s.recordMirrorCreatorGrant(ctx, request.AccountID, result.MirrorID, seedRole); operationErr != nil {
		s.enqueueMirrorPermsBackfill(ctx, request.Jurisdiction, request.ClusterSlug, githubRepoID)
		return mirrorID, nil //nolint:nilerr // Placement and enforcement are durable; reconciliation repairs listing metadata.
	}
	s.enqueueMirrorPermsBackfill(ctx, request.Jurisdiction, request.ClusterSlug, githubRepoID)
	return mirrorID, nil
}

func validateMirrorRequest(request mirrorrequest.Request) (string, string, *MirrorRequestError) {
	owner, repo := normalizeMirrorOwnerRepo(request.Owner, request.Repo)
	if strings.ToLower(request.Provider) != mirrorrepo.ProviderGitHub || owner == "" || repo == "" || request.ClusterSlug == "" || request.Jurisdiction == "" || request.AccountID == "" || request.GitHubUserID == 0 || request.MirrorID == nil {
		return "", "", invalidMirrorRequestFailure(errors.New("persisted mirror request is incomplete"))
	}
	return owner, repo, nil
}

func (s *Server) resolveMirrorRequestCluster(ctx context.Context, request mirrorrequest.Request) (string, string, *MirrorRequestError) {
	if s.cluster == nil {
		return "", "", InternalMirrorRequestFailure(errors.New("cluster registry not configured"))
	}
	cluster, err := s.cluster.GetBySlugGlobal(ctx, request.ClusterSlug)
	if err != nil {
		return "", "", InternalMirrorRequestFailure(fmt.Errorf("resolve cluster %q: %w", request.ClusterSlug, err))
	}
	if cluster.Jurisdiction != request.Jurisdiction || (s.jurisdiction != "" && cluster.Jurisdiction != s.jurisdiction) {
		return "", "", invalidMirrorRequestFailure(fmt.Errorf("cluster %q jurisdiction does not match request", request.ClusterSlug))
	}
	publicURL, err := url.Parse(cluster.PublicURL)
	if err != nil || publicURL.Host == "" {
		return "", "", InternalMirrorRequestFailure(fmt.Errorf("cluster %q has invalid public URL %q", request.ClusterSlug, cluster.PublicURL))
	}
	return publicURL.Host, cluster.PublicURL, nil
}

func mirrorRequestBootstrapFailure(err error) *MirrorRequestError {
	if blocked, ok := errors.AsType[*githubapp.MintBlockedError](err); ok && blocked != nil ||
		errors.Is(err, permssnapshotter.ErrAppNotInstalled) || errors.Is(err, permssnapshotter.ErrRepoBanned) {
		return repoInaccessibleMirrorRequestFailure(err)
	}
	if !isGitHubUnavailable(err) {
		return InternalMirrorRequestFailure(err)
	}
	return githubUnavailableMirrorRequestFailure(err)
}

func mirrorRequestSourceFailure(err error) *MirrorRequestError {
	if errors.Is(err, errMirrorSourceSizeNotConfigured) {
		return InternalMirrorRequestFailure(err)
	}
	if blocked, ok := errors.AsType[*githubapp.MintBlockedError](err); ok && blocked != nil {
		return repoInaccessibleMirrorRequestFailure(err)
	}
	if forbidden, ok := errors.AsType[*githubgraphql.ForbiddenError](err); ok && forbidden != nil {
		return repoInaccessibleMirrorRequestFailure(err)
	}
	if httpErr, ok := errors.AsType[*githubapi.HTTPError](err); ok && httpErr.Status == http.StatusNotFound {
		return repoInaccessibleMirrorRequestFailure(err)
	}
	if !isMirrorSourceGitHubUnavailable(err) {
		return InternalMirrorRequestFailure(err)
	}
	return githubUnavailableMirrorRequestFailure(err)
}

func isMirrorSourceGitHubUnavailable(err error) bool {
	if errors.Is(err, githubapi.ErrRateLimited) {
		return true
	}
	if rateLimited, ok := errors.AsType[*githubgraphql.RateLimitedError](err); ok && rateLimited != nil {
		return true
	}
	if transportErr, ok := errors.AsType[*url.Error](err); ok && transportErr != nil {
		return true
	}
	httpErr, ok := errors.AsType[*githubapi.HTTPError](err)
	if !ok {
		return false
	}
	switch httpErr.Status {
	case http.StatusUnauthorized, http.StatusForbidden, http.StatusRequestTimeout, http.StatusTooEarly, http.StatusTooManyRequests:
		return true
	default:
		return httpErr.Status >= 500 && httpErr.Status < 600
	}
}

func isGitHubUnavailable(err error) bool {
	if errors.Is(err, permssnapshotter.ErrInstallationUnhealthy) || errors.Is(err, githubapi.ErrRateLimited) {
		return true
	}
	if httpErr, ok := errors.AsType[*githubapi.HTTPError](err); ok && httpErr != nil {
		return true
	}
	transportErr, ok := errors.AsType[*url.Error](err)
	return ok && transportErr != nil
}

func mirrorRequestOperationFailure(err error) *MirrorRequestError {
	operationErr, ok := errors.AsType[*MirrorOpError](err)
	if !ok {
		return InternalMirrorRequestFailure(err)
	}
	if errors.Is(err, mirrorrepo.ErrURLConflict) {
		return &MirrorRequestError{Code: mirrorURLConflictFailureCode, Message: "mirror URL already in use", cause: err}
	}
	if errors.Is(err, regional.ErrNameConflict) {
		return &MirrorRequestError{Code: mirrorNameConflictFailureCode, Message: "a repo with that name already exists in the mirrors project", cause: err}
	}
	if errors.Is(err, mirrorrepo.ErrPlacementConflict) {
		return &MirrorRequestError{Code: mirrorRequestConflictFailureCode, Message: mirrorRequestConflictMessage, cause: err}
	}
	if errors.Is(err, mirrorrepo.ErrPlacementDeleted) {
		return &MirrorRequestError{Code: mirrorRequestPlacementDeletedFailureCode, Message: mirrorRequestPlacementDeletedMessage, cause: err}
	}
	switch operationErr.Status {
	case http.StatusNotFound:
		return repoInaccessibleMirrorRequestFailure(err)
	case http.StatusUnauthorized:
		return &MirrorRequestError{Code: mirrorRequestGitHubLinkFailureCode, Message: mirrorRequestGitHubLinkMessage, cause: err}
	case http.StatusBadGateway:
		return githubUnavailableMirrorRequestFailure(err)
	default:
		return InternalMirrorRequestFailure(err)
	}
}

func mirrorRequestPlacementFailure(err error) *MirrorRequestError {
	operationErr, ok := errors.AsType[*MirrorOpError](err)
	if ok && operationErr.Status == http.StatusBadGateway {
		return InternalMirrorRequestFailure(err)
	}
	return mirrorRequestOperationFailure(err)
}

func invalidMirrorRequestFailure(err error) *MirrorRequestError {
	return &MirrorRequestError{
		Code:    mirrorRequestInvalidFailureCode,
		Message: "mirror request is invalid",
		cause:   err,
	}
}

func repoInaccessibleMirrorRequestFailure(err error) *MirrorRequestError {
	return &MirrorRequestError{
		Code:    mirrorRequestRepoInaccessibleFailureCode,
		Message: mirrorRequestRepoInaccessibleMessage,
		cause:   err,
	}
}

func githubUnavailableMirrorRequestFailure(err error) *MirrorRequestError {
	return &MirrorRequestError{
		Code:      mirrorRequestGitHubFailureCode,
		Message:   mirrorRequestGitHubUnavailableMessage,
		Retryable: true,
		cause:     err,
	}
}

// MirrorRequestFailureRetryable mirrors, for failure codes read back from
// storage, the Retryable flag the failure constructors set when minting them.
func MirrorRequestFailureRetryable(code string) bool {
	return code == mirrorRequestGitHubFailureCode || code == mirrorRequestInternalFailureCode
}

// InternalMirrorRequestFailure is the retryable internal-error result of a
// persisted mirror request.
func InternalMirrorRequestFailure(err error) *MirrorRequestError {
	return &MirrorRequestError{
		Code:      mirrorRequestInternalFailureCode,
		Message:   mirrorRequestInternalMessage,
		Retryable: true,
		cause:     err,
	}
}

